interface AccessibilityPersistenceControlProps {
  persistenceStatus: string;
  savePreferences: boolean;
  onSavePreferencesChange: (value: boolean) => void;
}

export function AccessibilityPersistenceControl({ persistenceStatus, savePreferences, onSavePreferencesChange }: AccessibilityPersistenceControlProps) {
  return (
    <div className="overflow-hidden rounded-xl border border-slate-200 bg-white">
      <label htmlFor="save-accessibility-preferences" className="flex min-h-[72px] cursor-pointer items-center gap-[12px] p-[12px] hover:bg-slate-50">
        <input id="save-accessibility-preferences" type="checkbox" checked={savePreferences}
          aria-labelledby="save-accessibility-label" aria-describedby="save-accessibility-description"
          onChange={(event) => onSavePreferencesChange(event.target.checked)}
          className="h-[20px] w-[20px] shrink-0 cursor-pointer rounded border-slate-400 accent-brand-blue focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-brand-blue" />
        <span className="min-w-0">
          <span id="save-accessibility-label" className="block text-[14px] font-semibold text-brand-dark">Lembrar neste dispositivo</span>
          <span id="save-accessibility-description" className="mt-[4px] block text-[12px] leading-[18px] text-slate-600">Salva estas preferências no navegador.</span>
        </span>
      </label>
      <p className="mb-0 border-t border-slate-200 bg-slate-50 px-[12px] py-[10px] text-[12px] leading-[18px] text-slate-600" role="status">{persistenceStatus}</p>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { useLocation } from "react-router-dom";

const routeTitles: Array<[RegExp, string]> = [
  [/^\/$/, "Início"],
  [/^\/about$/, "Sobre nós"],
  [/^\/accessibility$/, "Acessibilidade"],
  [/^\/contact$/, "Contato"],
  [/^\/login$/, "Entrar"],
  [/^\/forgot-password$/, "Recuperar senha"],
  [/^\/reset-password$/, "Redefinir senha"],
  [/^\/shop$/, "Loja"],
  [/^\/pre-register$/, "Escolher perfil"],
  [/^\/register\/customer$/, "Cadastro de cliente"],
  [/^\/register\/seller$/, "Cadastro de vendedor"],
  [/^\/seller\/dashboard$/, "Painel do vendedor"],
  [/^\/seller\/edit-profile$/, "Editar perfil do vendedor"],
  [/^\/seller\/add-product$/, "Cadastrar produto"],
  [/^\/seller\/edit-product\//, "Editar produto"],
  [/^\/seller\/store\//, "Loja do vendedor"],
  [/^\/customer\/dashboard$/, "Painel do comprador"],
  [/^\/customer\/orders\//, "Detalhes do pedido"],
  [/^\/customer\/edit-profile$/, "Editar perfil"],
  [/^\/checkout$/, "Finalizar compra"],
  [/^\/payment\/development\//, "Pagamento simulado"],
  [/^\/payment\/success$/, "Pagamento recebido"],
  [/^\/payment\/pending$/, "Pagamento pendente"],
  [/^\/payment\/failure$/, "Pagamento não concluído"],
  [/^\/shipping$/, "Selecionar entrega"],
  [/^\/addresses\/new$/, "Adicionar endereço"],
  [/^\/addresses$/, "Endereços"],
  [/^\/two-factor-setup$/, "Configurar verificação em duas etapas"],
  [/^\/change-password$/, "Alterar senha"],
  [/^\/product\//, "Detalhes do produto"],
  [/^\/shared-purchases$/, "Compras compartilhadas"],
];

const getRouteTitle = (pathname: string) =>
  routeTitles.find(([pattern]) => pattern.test(pathname))?.[1] ??
  "Página não encontrada";

export function RouteAccessibility() {
  const location = useLocation();
  const previousPathname = useRef(location.pathname);
  const [announcement, setAnnouncement] = useState("");
  const routeTitle = useMemo(
    () => getRouteTitle(location.pathname),
    [location.pathname],
  );

  useEffect(() => {
    document.title = `${routeTitle} | Inclusivo`;
    setAnnouncement("");
    const announceTimer = window.setTimeout(
      () => setAnnouncement(`${routeTitle}, página carregada.`),
      100,
    );

    if (previousPathname.current === location.pathname) {
      return () => window.clearTimeout(announceTimer);
    }
    previousPathname.current = location.pathname;

    const frame = requestAnimationFrame(() => {
      const target =
        document.querySelector<HTMLElement>("main h1") ??
        document.querySelector<HTMLElement>("main");
      if (!target) return;

      const hadTabIndex = target.hasAttribute("tabindex");
      if (!hadTabIndex) target.setAttribute("tabindex", "-1");
      target.focus({ preventScroll: false });
      if (!hadTabIndex) {
        target.addEventListener(
          "blur",
          () => target.removeAttribute("tabindex"),
          { once: true },
        );
      }
    });

    return () => {
      window.clearTimeout(announceTimer);
      cancelAnimationFrame(frame);
    };
  }, [location.pathname, routeTitle]);

  return (
    <p className="sr-only" role="status" aria-live="polite" aria-atomic="true">
      {announcement}
    </p>
  );
}

export interface LoginMessageData {
  type: "success" | "error" | "info";
  text: string;
}

interface LoginMessageProps {
  message: LoginMessageData | null;
}

export function LoginMessage({ message }: LoginMessageProps) {
  if (!message) return null;

  return (
    <div
      className={`mb-4 rounded-lg border p-3 text-center font-medium shadow-sm ${
        message.type === "success"
          ? "border-green-200 bg-green-50 text-green-800"
          : message.type === "info"
            ? "border-brand-blue/20 bg-brand-blue/10 text-brand-blue"
            : "border-red-200 bg-red-50 text-red-800"
      }`}
      role={message.type === "error" ? "alert" : "status"}
      aria-live={message.type === "error" ? "assertive" : "polite"}
      aria-atomic="true"
    >
      {message.text}
    </div>
  );
}

import "./chat.css";
import { ChatProductContext } from "@/components/chat/ChatProductContext";
import { ChatComposer } from "@/components/chat/ChatComposer";
import { ChatConversationList } from "@/components/chat/ChatConversationList";
import { ChatEmptyState } from "@/components/chat/ChatEmptyState";
import { ChatMessageList } from "@/components/chat/ChatMessageList";
import { ChatReportDialog } from "@/components/chat/ChatReportDialog";
import { ChatThreadHeader } from "@/components/chat/ChatThreadHeader";
import { useChatCenter } from "@/hooks/useChatCenter";
import { useChatReportDialog } from "@/hooks/useChatReportDialog";

type Props = {
  embedded?: boolean;
  dedicated?: boolean;
};

export function ChatCenter({ embedded = false, dedicated = false }: Props) {
  const chat = useChatCenter();
  const reportDialog = useChatReportDialog(chat.reportMessage);
  const isTyping = chat.typingConversationId === chat.activeConversationId;
  const chatHeight = dedicated
    ? "min-h-0 flex-1"
    : embedded
    ? "h-[72dvh] min-h-[480px] lg:h-[min(680px,calc(100dvh-112px))]"
    : "h-[calc(100dvh-145px)] min-h-[480px]";

  return (
    <div className={dedicated ? "flex h-full min-h-0 flex-col" : undefined}>
      {chat.error && (
        <div
          role="alert"
          className="mb-4 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700"
        >
          {chat.error}
        </div>
      )}
      {chat.moderationNotice && (
        <div
          role="status"
          className="mb-4 rounded-lg border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-700"
        >
          {chat.moderationNotice}
        </div>
      )}

      <div
        role="region"
        aria-label="Central de mensagens"
        className={`grid ${chatHeight} min-w-0 scroll-mt-24 overflow-hidden border border-brand-blue/15 bg-white shadow-sm rounded-2xl lg:grid-cols-[280px_minmax(0,1fr)]`}
      >
        <ChatConversationList
          activeConversationId={chat.activeConversationId}
          conversations={chat.conversations}
          drafts={chat.conversationDrafts}
          isThreadOpen={Boolean(chat.activeConversation)}
          loading={chat.loading}
          onSelect={chat.selectConversation}
        />
        <div
          className={`min-h-0 min-w-0 overflow-hidden bg-white ${
            chat.activeConversation ? "grid" : "hidden"
          } ${chat.activeConversation?.product_id ? "xl:grid-cols-[minmax(0,1fr)_260px]" : "grid-cols-1"}`}
        >
          <div className="flex min-h-0 min-w-0 flex-col overflow-hidden">
            <ChatThreadHeader
              conversation={chat.activeConversation}
              isTyping={isTyping}
              onBlock={chat.blockPeer}
              onBack={() => chat.selectConversation(null)}
              onUnblock={chat.unblockPeer}
            />
            {chat.activeConversation?.product_id && (
              <div className="shrink-0 xl:hidden">
                <ChatProductContext key={chat.activeConversation.id} conversation={chat.activeConversation} collapsible />
              </div>
            )}
            {(chat.activeConversation?.blocked_by_me ||
              chat.activeConversation?.blocked_by_peer) && (
              <div className="border-b border-amber-200 bg-amber-50 px-4 py-2 text-sm text-amber-800">
                {chat.activeConversation.blocked_by_me
                  ? "Você bloqueou este usuário. Desbloqueie para voltar a enviar mensagens."
                  : "Este usuário bloqueou a conversa. O envio de mensagens está indisponível."}
              </div>
            )}
            <ChatMessageList
              isTyping={isTyping}
              messages={chat.messages}
              onReportMessage={reportDialog.openReport}
              peerName={chat.activeConversation?.peer.name}
              userId={chat.userId}
            />
            <ChatComposer
              allowAttachments={chat.isDemoMode}
              attachments={chat.attachments}
              disabled={
                !chat.activeConversation ||
                Boolean(
                  chat.activeConversation.blocked_by_me ||
                  chat.activeConversation.blocked_by_peer,
                )
              }
              draft={chat.draft}
              onAddAttachments={chat.addAttachments}
              onChange={chat.handleDraftChange}
              onRemoveAttachment={chat.removeAttachment}
              onSend={chat.sendMessage}
              sending={chat.sending}
            />
          </div>
          {chat.activeConversation?.product_id && (
            <aside aria-label="Detalhes do produto" className="hidden min-h-0 overflow-y-auto border-l border-slate-200 bg-slate-50 p-5 xl:block">
              <ChatProductContext conversation={chat.activeConversation} sidebar />
            </aside>
          )}
        </div>
        {!chat.activeConversation && (
          <div className={`chat-history hidden min-h-0 lg:flex`}>
            <ChatEmptyState
              title="Suas mensagens"
              description="Escolha uma conversa na barra lateral para abrir o histórico de mensagens."
            />
          </div>
        )}
      </div>
      <ChatReportDialog
        details={reportDialog.details}
        isOpen={reportDialog.isOpen}
        onClose={reportDialog.closeReport}
        onDetailsChange={reportDialog.setDetails}
        onReasonChange={reportDialog.setReason}
        onSubmit={reportDialog.submitReport}
        reason={reportDialog.reason}
        submitting={reportDialog.submitting}
      />
    </div>
  );
}

import { useState } from "react";
import { MessageSquare, Search } from "lucide-react";
import type { ChatConversation } from "@/types/chat";
import { useChatConversationFilter } from "@/hooks/useChatConversationFilter";
import { ChatSkeleton } from "./ChatSkeleton";
import { ConversationItem } from "./ConversationItem";

type Props = {
  activeConversationId: number | null;
  conversations: ChatConversation[];
  drafts?: Record<number, string>;
  isThreadOpen: boolean;
  loading: boolean;
  onSelect: (id: number) => void;
};

export function ChatConversationList({
  activeConversationId,
  conversations,
  drafts = {},
  isThreadOpen,
  loading,
  onSelect,
}: Props) {
  const { filteredConversations, query, setQuery } =
    useChatConversationFilter(conversations);

  const [unreadOnly, setUnreadOnly] = useState(false);
  const unreadCount = conversations.filter(item => item.unread_count > 0).length;
  // Keep the selected thread in view after acknowledging its unread messages.
  const visibleConversations = filteredConversations.filter(item =>
    !unreadOnly || item.unread_count > 0 || item.id === activeConversationId,
  );

  return (
    <aside
      className={`min-h-0 flex-col overflow-hidden border-r border-slate-200 bg-white lg:flex ${
        isThreadOpen ? "hidden" : "flex"
      }`}
    >
      <div className="shrink-0 border-b border-slate-200">
        <div className="flex items-center gap-3 bg-brand-blue px-5 py-5 text-white">
          <span className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl border border-white/20 bg-white/10">
            <MessageSquare className="h-5 w-5" strokeWidth={1.75} aria-hidden="true" />
          </span>
          <div className="min-w-0">
            <h2 className="text-lg font-bold leading-6 tracking-tight">Mensagens</h2>
            <p className="mt-0.5 text-sm leading-5">
              {conversations.length} {conversations.length === 1 ? "conversa" : "conversas"}
            </p>
          </div>
        </div>
        <div className="space-y-3 bg-white p-4">
          <label className="relative block">
            <span className="sr-only">Buscar conversa</span>
            <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500" aria-hidden="true" />
            <input
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="Buscar conversa"
              className="h-11 w-full rounded-xl border border-slate-200 bg-slate-50 pl-9 pr-3 text-base text-slate-900 outline-none transition-colors duration-200 placeholder:text-slate-500 focus:border-brand-blue/50 focus:bg-white focus-visible:ring-2 focus-visible:ring-brand-blue/20"
            />
          </label>
          <div className="grid grid-cols-2 gap-1 rounded-xl border border-slate-200 bg-slate-100 p-1" role="group" aria-label="Filtrar conversas">
            {[
              { label: "Todas", value: false, count: conversations.length },
              { label: "Não lidas", value: true, count: unreadCount },
            ].map(filter => (
              <button
                key={filter.label}
                type="button"
                aria-pressed={unreadOnly === filter.value}
                onClick={() => setUnreadOnly(filter.value)}
                className={`inline-flex min-h-11 min-w-0 items-center justify-center gap-1.5 rounded-lg px-2 text-sm font-semibold transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-blue ${unreadOnly === filter.value ? "bg-white text-brand-blue shadow-sm" : "text-slate-600 hover:bg-white/70"}`}
              >
                {filter.label}
                <span className={`grid min-h-5 min-w-5 place-items-center rounded-md px-1 text-xs ${unreadOnly === filter.value ? "bg-brand-blue/10 text-brand-blue" : "bg-slate-200 text-slate-600"}`}>
                  {filter.count}
                </span>
              </button>
            ))}
          </div>
        </div>
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain bg-white px-2 py-2">
        {loading && <ChatSkeleton />}
        {!loading && conversations.length === 0 && (
          <p className="p-4 text-sm leading-6 text-slate-500">
            Nenhuma conversa iniciada ainda.
          </p>
        )}
        {!loading &&
          conversations.length > 0 &&
          visibleConversations.length === 0 && (
            <p className="p-4 text-sm leading-6 text-slate-500">
              {unreadOnly && !query.trim() ? "Nenhuma conversa não lida por aqui." : "Nenhuma conversa encontrada."}
            </p>
          )}
        {visibleConversations.map((conversation) => (
          <ConversationItem
            key={conversation.id}
            conversation={conversation}
            draft={drafts[conversation.id]}
            isActive={activeConversationId === conversation.id}
            onSelect={onSelect}
          />
        ))}
      </div>
    </aside>
  );
}

type Props = {
  peerName?: string;
};

export function TypingIndicator({ peerName = "Contato" }: Props) {
  return (
    <div
      className="flex justify-start motion-safe:animate-[chat-message-in_180ms_ease-out]"
      role="status"
      aria-live="polite"
    >
      <div className="flex items-center gap-2 rounded-2xl rounded-tl-sm border border-slate-200 bg-white px-4 py-3 text-sm text-slate-500 shadow-sm">
        <span>{peerName} está digitando</span>
        <span className="flex gap-1" aria-hidden="true">
          <span className="h-1.5 w-1.5 animate-bounce rounded-full bg-slate-400 [animation-delay:-0.2s]" />
          <span className="h-1.5 w-1.5 animate-bounce rounded-full bg-slate-400 [animation-delay:-0.1s]" />
          <span className="h-1.5 w-1.5 animate-bounce rounded-full bg-slate-400" />
        </span>
      </div>
    </div>
  );
}

import { Link } from "react-router-dom";
import { CreditCard } from "lucide-react";
import { Button } from "@/components/ui/button";
import type { OrderDetailData } from "./orderDetailTypes";
import { orderStatusInfo } from "./orderDetailUtils";

interface OrderDetailHeaderProps {
  order: OrderDetailData;
  resumeState?: Record<string, unknown>;
}

export function OrderDetailHeader({
  order,
  resumeState,
}: OrderDetailHeaderProps) {
  const meta = orderStatusInfo[order.status] || orderStatusInfo.pending;
  const StatusIcon = meta.icon;

  return (
    <div className="mt-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
      <div>
        <p className="text-xs font-bold uppercase tracking-[0.18em] text-brand-blue">
          Detalhes da compra
        </p>
        <div className="mt-1.5">
          <h1 className="text-3xl font-bold leading-tight text-slate-900">
            Pedido #{order.id}
          </h1>
          <p className="mt-1 text-sm text-slate-500">
            Realizado em {new Date(order.created_at).toLocaleString("pt-BR")}
          </p>
        </div>
      </div>
      <div className="space-y-2">
        <div
          className={`${meta.className} sm:min-w-[220px] rounded-lg px-5 py-3.5 shadow-sm`}
          role="status"
          aria-label={`Status do pedido: ${meta.label}`}
        >
          <p className="text-[11px] font-bold uppercase tracking-[0.18em] opacity-70">
            Status do pedido
          </p>
          <div className="mt-1.5 flex items-center gap-2.5">
            <StatusIcon className="h-5 w-5" />
            <span className="text-base font-bold">{meta.label}</span>
          </div>
        </div>
        {order.payment_provider === "development" && (
          <Button asChild variant="outline" className="w-full">
            <Link to={`/payment/development/${order.id}`}>
              Controlar pagamento simulado
            </Link>
          </Button>
        )}
        {resumeState &&
          order.status === "pending" &&
          order.cancellation_status !== "pending" && (
            <Button
              asChild
              className="w-full bg-brand-orange text-white hover:bg-brand-orange/90"
            >
              <Link to="/checkout" state={resumeState}>
                <CreditCard className="mr-2 h-4 w-4" />
                Finalizar pagamento
              </Link>
            </Button>
          )}
      </div>
    </div>
  );
}

import { ReceiptText } from "lucide-react";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";
import type { OrderDetailData } from "./orderDetailTypes";
import { formatOrderCurrency, orderPaymentLabels } from "./orderDetailUtils";

interface OrderSummaryCardProps {
  order: OrderDetailData;
  totals: { products: number; shipping: number };
}

export function OrderSummaryCard({ order, totals }: OrderSummaryCardProps) {
  return (
    <aside>
      <Card className="lg:sticky lg:top-24 border-slate-200 shadow-sm">
        <CardHeader>
          <h2 className="flex items-center gap-2 text-2xl font-semibold">
            <ReceiptText className="h-5 w-5 text-brand-blue" />
            Resumo do pedido
          </h2>
        </CardHeader>
        <CardContent className="space-y-4">
          <SummaryRow
            label="Produtos"
            value={formatOrderCurrency(totals.products)}
          />
          <SummaryRow
            label="Frete"
            value={formatOrderCurrency(totals.shipping)}
          />
          {Number(order.discount_amount || 0) > 0 && (
            <SummaryRow
              label={`Cupom ${order.coupon_code || ""}`.trim()}
              value={`-${formatOrderCurrency(Number(order.discount_amount || 0))}`}
            />
          )}
          <SummaryRow
            label="Pagamento"
            value={
              order.payment_method
                ? orderPaymentLabels[order.payment_method] ||
                  order.payment_method
                : "Não informado"
            }
          />
          {order.payment_status && (
            <SummaryRow
              label="Status no provedor"
              value={order.payment_status}
            />
          )}
          {order.paid_at && (
            <SummaryRow
              label="Pago em"
              value={new Date(order.paid_at).toLocaleString("pt-BR")}
            />
          )}
          {order.cancellation_status && (
            <div
              role="status"
              className="rounded-lg border border-slate-200 bg-slate-50 p-3 text-sm text-slate-700"
            >
              <p className="font-semibold">
                {order.cancellation_status === "pending"
                  ? "Cancelamento em conciliação"
                  : "Cancelamento conciliado"}
              </p>
              <p className="mt-1">
                {order.cancellation_status === "pending"
                  ? "O pedido está cancelado. Estamos verificando o cancelamento das cobranças e os estornos necessários."
                  : order.payment_status === "refunded"
                    ? "O reembolso foi confirmado pelo provedor de pagamento."
                    : "As cobranças deste pedido foram encerradas."}
              </p>
            </div>
          )}
          <Separator />
          <div className="flex items-end justify-between">
            <span className="font-semibold text-slate-900">Total</span>
            <span className="text-2xl font-bold text-brand-blue">
              {formatOrderCurrency(order.total_amount)}
            </span>
          </div>
          <p className="rounded-lg bg-slate-50 p-3 text-xs leading-5 text-slate-500">
            Última atualização em{" "}
            {new Date(order.updated_at).toLocaleString("pt-BR")}.
          </p>
        </CardContent>
      </Card>
    </aside>
  );
}

function SummaryRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex justify-between text-slate-600">
      <span>{label}</span>
      <span>{value}</span>
    </div>
  );
}

import { Star } from "lucide-react";
import { cn } from "@/lib/utils";

type SellerRatingInputProps = {
  value: number;
  onChange: (value: number) => void;
  disabled?: boolean;
};

export function SellerRatingInput({
  value,
  onChange,
  disabled,
}: SellerRatingInputProps) {
  return (
    <div className="flex items-center gap-1" role="radiogroup" aria-label="Nota do vendedor">
      {[1, 2, 3, 4, 5].map((rating) => (
        <button
          key={rating}
          type="button"
          disabled={disabled}
          onClick={() => onChange(rating)}
          className="rounded-full p-1 transition hover:scale-110 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-blue/30 disabled:cursor-not-allowed"
          aria-label={`${rating} estrela${rating > 1 ? "s" : ""}`}
          aria-checked={value === rating}
          role="radio"
        >
          <Star
            className={cn(
              "h-6 w-6 transition",
              rating <= value
                ? "fill-brand-orange text-brand-orange"
                : "text-slate-300 hover:text-brand-orange/70",
            )}
          />
        </button>
      ))}
    </div>
  );
}

import { getSharedParticipantAmount } from "@/lib/sharedPurchaseRules";
import { useState } from "react";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogCancel,
  AlertDialogAction,
} from "@/components/ui/alert-dialog";
import {
  CheckCircle2,
  Clock3,
  CreditCard,
  Footprints,
  PackageCheck,
  RefreshCw,
  UsersRound,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { sideLabel } from "@/lib/sharedPurchases";
import { useCustomerSharedPurchases } from "@/hooks/useCustomerSharedPurchases";
import type { SharedPurchaseReservation } from "@/types/shared-purchase";

const money = (value: number) =>
  value.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

const paymentLabels: Record<string, string> = {
  approved: "confirmado",
  accredited: "confirmado",
  pending: "aguardando pagamento",
  creating: "iniciando pagamento",
  in_process: "em análise",
  authorized: "autorizado",
  refunded: "reembolsado",
  cancelled: "cancelado",
  rejected: "não aprovado",
  charged_back: "contestado",
};
const paymentLabel = (value?: string | null) =>
  value ? paymentLabels[value] || "em atualização" : "não iniciado";

const statusMeta = {
  expired: {
    label: "Prazo encerrado",
    className: "bg-slate-100 text-slate-700",
    icon: Clock3,
  },
  cancelled: {
    label: "Reserva cancelada",
    className: "bg-slate-100 text-slate-700",
    icon: Clock3,
  },
  refund_pending: {
    label: "Cancelamento/reembolso em processamento",
    className: "bg-orange-50 text-orange-800",
    icon: Clock3,
  },
  waiting: {
    label: "Aguardando par",
    className: "bg-orange-50 text-orange-700 ring-orange-200",
    icon: Clock3,
  },
  matched: {
    label: "Par encontrado",
    className: "bg-emerald-50 text-emerald-700 ring-emerald-200",
    icon: CheckCircle2,
  },
  completed: {
    label: "Pagamentos confirmados",
    className: "bg-brand-blue/10 text-brand-blue ring-brand-blue/20",
    icon: PackageCheck,
  },
};

export function SharedPurchasesTab() {
  const shared = useCustomerSharedPurchases();
  const [cancelTarget, setCancelTarget] =
    useState<SharedPurchaseReservation | null>(null);

  return (
    <div className="space-y-6">
      <header>
        <p className="text-xs font-bold uppercase tracking-[0.16em] text-brand-blue">
          Compra compartilhada
        </p>
        <h2 className="mt-1 text-2xl font-bold text-slate-900">
          Seus pares compartilhados
        </h2>
        <p className="mt-2 max-w-2xl text-sm text-slate-600">
          Acompanhe reservas, veja quando o par for encontrado e siga para o
          pagamento apenas do pé que você vai receber.
        </p>
      </header>

      <div className="grid gap-3 sm:grid-cols-3">
        <SharedMetric label="Aguardando par" value={shared.stats.waiting} />
        <SharedMetric label="Par encontrado" value={shared.stats.matched} />
        <SharedMetric
          label="Pagamentos confirmados"
          value={shared.stats.completed}
        />
      </div>

      {shared.error && (
        <div
          role="alert"
          className="rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-700"
        >
          {shared.error}
        </div>
      )}

      {shared.loading ? (
        <div className="rounded-lg border border-slate-200 bg-white p-elevated text-center text-slate-500">
          Carregando suas reservas...
        </div>
      ) : shared.reservations.length === 0 ? (
        <SharedEmptyState />
      ) : (
        <div className="space-y-4">
          {shared.reservations.map((reservation) => (
            <SharedReservationDashboardCard
              key={reservation.id}
              orderId={shared.getOrderId(reservation)}
              reservation={reservation}
              side={shared.getReservationSide(reservation)}
              onCheckout={() => shared.goToCheckout(reservation)}
              onOrder={() => shared.goToOrder(reservation)}
              onCancel={() => setCancelTarget(reservation)}
              cancelling={shared.cancelling === reservation.id}
            />
          ))}
        </div>
      )}

      <AlertDialog
        open={cancelTarget !== null}
        onOpenChange={(open) => {
          if (!open) setCancelTarget(null);
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Cancelar a reserva deste par?</AlertDialogTitle>
            <AlertDialogDescription>
              A reserva será encerrada para os dois compradores. Se houver
              pagamento, o cancelamento ou reembolso será acompanhado até a
              confirmação do provedor.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Manter reserva</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => {
                if (cancelTarget) void shared.cancelReservation(cancelTarget);
              }}
            >
              Confirmar cancelamento
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
      <Button
        type="button"
        variant="outline"
        className="gap-2"
        onClick={shared.refresh}
      >
        <RefreshCw className="h-4 w-4" />
        Atualizar reservas
      </Button>
    </div>
  );
}

function SharedMetric({ label, value }: { label: string; value: number }) {
  return (
    <div className="rounded-lg border border-slate-200 bg-white p-4 shadow-sm">
      <p className="text-2xl font-bold text-slate-900">{value}</p>
      <p className="mt-1 text-sm text-slate-500">{label}</p>
    </div>
  );
}

function SharedReservationDashboardCard({
  orderId,
  reservation,
  side,
  onCheckout,
  onCancel,
  onOrder,
  cancelling,
}: {
  orderId?: number | null;
  reservation: SharedPurchaseReservation;
  side: "left" | "right";
  onCheckout: () => void;
  onCancel: () => void;
  onOrder: () => void;
  cancelling: boolean;
}) {
  const meta = statusMeta[reservation.status] || statusMeta.waiting;
  const StatusIcon = meta.icon;
  const canPay = reservation.status === "matched" && !orderId;

  return (
    <article className="overflow-hidden rounded-lg border border-slate-200 bg-white shadow-sm">
      <div className="flex flex-col gap-3 p-card sm:gap-4 sm:flex-row sm:items-center">
        <img
          src={reservation.product.imageUrl || "/placeholder.svg"}
          alt=""
          className="h-24 w-24 rounded-lg border border-slate-100 bg-slate-100 object-cover"
        />
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-2">
            <span
              className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-semibold ring-1 ${meta.className}`}
            >
              <StatusIcon className="h-3.5 w-3.5" />
              {meta.label}
            </span>
            <span className="text-xs font-semibold text-slate-500">
              Reserva #{reservation.id}
            </span>
          </div>
          <h3 className="mt-2 line-clamp-1 text-lg font-bold text-slate-900">
            {reservation.product.name}
          </h3>
          <p className="mt-1 text-sm text-slate-500">
            Seu lado: <strong>{sideLabel(side)}</strong> · Valor:{" "}
            <strong>
              {money(getSharedParticipantAmount(reservation, side))}
            </strong>
          </p>
        </div>

        {canPay ? (
          <Button onClick={onCheckout} className="gap-2 bg-brand-blue">
            <CreditCard className="h-4 w-4" />
            Ir para pagamento
          </Button>
        ) : orderId ? (
          <Button variant="outline" onClick={onOrder}>
            Ver pedido #{orderId}
          </Button>
        ) : reservation.status === "waiting" ? (
          <span className="rounded-lg bg-orange-50 px-3 py-2 text-sm font-semibold text-orange-700">
            Aguardando outro comprador
          </span>
        ) : null}
        {["waiting", "matched"].includes(reservation.status) && (
          <Button
            type="button"
            variant="outline"
            onClick={onCancel}
            disabled={cancelling}
          >
            {cancelling ? "Cancelando…" : "Cancelar reserva"}
          </Button>
        )}
      </div>

      <p className="px-4 pb-3 text-sm text-slate-600">
        Prazo da reserva:{" "}
        {new Date(reservation.expiresAt).toLocaleString("pt-BR")}.
      </p>
      <p className="px-4 pb-3 text-sm text-slate-600">
        Pagamento do primeiro comprador:{" "}
        {paymentLabel(reservation.creatorPaymentStatus)}. Pagamento do segundo:{" "}
        {paymentLabel(reservation.partnerPaymentStatus)}.
      </p>
      {reservation.status === "refund_pending" && (
        <p role="status" className="px-4 pb-3 text-sm text-orange-800">
          O estoque permanece protegido enquanto o provedor confirma o
          cancelamento ou reembolso. Atualize para acompanhar.
        </p>
      )}
      <div className="grid border-t border-slate-100 bg-slate-50 sm:grid-cols-2">
        <SharedSideInfo
          buyer={reservation.creatorName}
          label="Primeiro comprador"
          side={reservation.reservedSide}
        />
        <SharedSideInfo
          buyer={reservation.partnerName || "Aguardando comprador"}
          label="Segundo comprador"
          side={reservation.reservedSide === "left" ? "right" : "left"}
        />
      </div>
    </article>
  );
}

function SharedSideInfo({
  buyer,
  label,
  side,
}: {
  buyer: string;
  label: string;
  side: "left" | "right";
}) {
  return (
    <div className="flex items-center gap-3 border-slate-100 p-4 sm:border-r">
      <span className="grid h-10 w-10 place-items-center rounded-full bg-white text-brand-blue shadow-sm">
        <Footprints className="h-4 w-4" />
      </span>
      <div>
        <p className="text-xs font-semibold uppercase tracking-wide text-slate-500">
          {label}
        </p>
        <p className="text-sm font-bold text-slate-900">{buyer}</p>
        <p className="text-xs text-slate-500">{sideLabel(side)}</p>
      </div>
    </div>
  );
}

function SharedEmptyState() {
  return (
    <div className="rounded-lg border border-dashed border-slate-300 bg-white px-4 py-8 text-center sm:px-6 sm:py-12">
      <UsersRound className="mx-auto h-9 w-9 text-slate-500" />
      <h3 className="mt-3 text-lg font-bold text-slate-900">
        Nenhuma reserva compartilhada
      </h3>
      <p className="mt-1 text-sm text-slate-500">
        Quando você reservar um lado de um par completo, o acompanhamento
        aparece aqui.
      </p>
    </div>
  );
}

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { Link, useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { useAuth } from "@/contexts/AuthContext";
import { useDocumentAnchorDropdown } from "@/hooks/useDocumentAnchorDropdown";
import {
  ChevronDown,
  ChevronRight,
  Heart,
  LayoutDashboard,
  LogOut,
  MapPin,
  Package,
  KeyRound,
  Shield,
  ShoppingBag,
  Store,
  User,
  UserRound,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";

const MENU_WIDTH = 320;

type MenuLink = {
  label: string;
  to: string;
  icon: LucideIcon;
};

function MenuLinkItem({
  item,
  onNavigate,
}: {
  item: MenuLink;
  onNavigate: () => void;
}) {
  const Icon = item.icon;

  return (
    <Link
      to={item.to}
      onClick={onNavigate}
      className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium text-brand-dark outline-none transition hover:bg-brand-blue/8 focus-visible:bg-brand-blue/8 focus-visible:ring-2 focus-visible:ring-brand-blue focus-visible:ring-offset-2"
    >
      <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-slate-100 text-brand-blue">
        <Icon className="h-4 w-4" />
      </span>
      <span className="flex-1">{item.label}</span>
      <ChevronRight className="h-4 w-4 text-slate-500" />
    </Link>
  );
}

export function ProfileMenuDropdown() {
  const { user, logout, userType, sellerId } = useAuth();
  const navigate = useNavigate();
  const [isOpen, setIsOpen] = useState(false);
  const closeMenu = () => setIsOpen(false);

  const { triggerRef, menuRef, position, updatePosition } =
    useDocumentAnchorDropdown(isOpen, MENU_WIDTH, closeMenu);

  useEffect(() => {
    if (isOpen) {
      requestAnimationFrame(updatePosition);
    }
  }, [isOpen, updatePosition]);

  if (!user) return null;

  const isSeller = userType === "seller" || user.type === "seller";
  const firstName = user.name.split(" ")[0];
  const AvatarIcon = isSeller ? Store : UserRound;

  const dashboardPath = isSeller ? "/seller/dashboard" : "/customer/dashboard";
  const profilePath = isSeller
    ? "/seller/edit-profile"
    : "/customer/edit-profile";

  const accountLinks: MenuLink[] = isSeller
    ? [
        ...(sellerId
          ? [
              {
                label: "Minha loja",
                to: `/seller/store/${sellerId}`,
                icon: Store,
              },
            ]
          : []),
        {
          label: "Adicionar produto",
          to: "/seller/add-product",
          icon: Package,
        },
        { label: "Editar perfil", to: profilePath, icon: User },
      ]
    : [
        { label: "Explorar loja", to: "/shop", icon: ShoppingBag },
        { label: "Meus endereços", to: "/addresses", icon: MapPin },
        { label: "Editar perfil", to: profilePath, icon: User },
      ];

  const securityLinks: MenuLink[] = [
    { label: "Alterar senha", to: "/change-password", icon: KeyRound },
    {
      label: "Verificação em duas etapas",
      to: "/two-factor-setup",
      icon: Shield,
    },
  ];

  const handleLogout = async () => {
    closeMenu();
    await logout();
    navigate("/login");
  };

  const menuPanel = isOpen ? (
    <div
      id="profile-menu-panel"
      ref={menuRef}
      role="navigation"
      aria-label="Menu da conta"
      style={{
        position: "absolute",
        top: position.top,
        left: position.left,
        width: MENU_WIDTH,
      }}
      className="z-[100] overflow-visible rounded-xl border border-slate-200 bg-white shadow-xl"
    >
      <div
        className="h-1 rounded-t-xl bg-gradient-to-r from-brand-blue via-sky-300 to-brand-orange"
        aria-hidden
      />

      <div className="flex items-start gap-3 border-b border-slate-100 px-4 py-4">
        <Avatar className="h-12 w-12 shrink-0">
          <AvatarImage src={user.avatar_url || undefined} alt="" />
          <AvatarFallback><AvatarIcon className="h-5 w-5" /></AvatarFallback>
        </Avatar>

        <div className="min-w-0 flex-1 pt-0.5">
          <p className="truncate font-bold leading-tight text-brand-dark">
            {user.name}
          </p>
          <p className="mt-0.5 truncate text-xs text-slate-500">{user.email}</p>
        </div>
      </div>

      <div className="p-2">
        <Link
          to={dashboardPath}
          onClick={closeMenu}
          className="flex items-center gap-3 rounded-lg bg-brand-orange px-3 py-3 text-sm font-semibold text-white shadow-sm transition hover:bg-orange-800 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-orange focus-visible:ring-offset-2"
        >
          <LayoutDashboard className="h-4 w-4 shrink-0" />
          <span className="flex-1">
            {isSeller ? "Abrir painel" : "Ir para minha conta"}
          </span>
          <ChevronRight className="h-4 w-4 opacity-80" />
        </Link>
      </div>

      <div className="mx-2 h-px bg-slate-100" />

      <div className="space-y-0.5 p-2">
        <p className="px-3 pb-1 pt-0.5 text-xs font-semibold uppercase tracking-wider text-slate-500">
          {isSeller ? "Vendas" : "Compras"}
        </p>
        {accountLinks.map((item) => (
          <MenuLinkItem
            key={item.to + item.label}
            item={item}
            onNavigate={closeMenu}
          />
        ))}
        {!isSeller && (
          <MenuLinkItem
            item={{
              label: "Favoritos",
              to: `${dashboardPath}?tab=wishlist`,
              icon: Heart,
            }}
            onNavigate={closeMenu}
          />
        )}
      </div>

      <div className="mx-2 h-px bg-slate-100" />

      <div className="space-y-0.5 p-2">
        <p className="px-3 pb-1 pt-0.5 text-xs font-semibold uppercase tracking-wider text-slate-500">
          Segurança
        </p>
        {securityLinks.map((item) => (
          <MenuLinkItem
            key={item.to + item.label}
            item={item}
            onNavigate={closeMenu}
          />
        ))}
      </div>

      <div className="mx-2 h-px bg-slate-100" />

      <div className="p-2 pb-3">
        <button
          type="button"
          onClick={handleLogout}
          className="flex w-full items-center rounded-lg px-3 py-2.5 text-sm font-medium text-red-600 transition hover:bg-red-50 hover:text-red-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-500 focus-visible:ring-offset-2"
        >
          <LogOut className="mr-2 h-4 w-4" />
          Sair da conta
        </button>
      </div>
    </div>
  ) : null;

  return (
    <>
      <Button
        ref={triggerRef}
        type="button"
        variant="ghost"
        onClick={() => setIsOpen((open) => !open)}
        aria-expanded={isOpen}
        aria-controls="profile-menu-panel"
        aria-haspopup="menu"
        className="h-10 gap-2 rounded-full border border-gray-200 bg-white px-3 text-brand-dark shadow-sm hover:border-brand-blue/30 hover:bg-brand-blue/5 hover:text-brand-blue data-[state=open]:border-brand-blue/40 data-[state=open]:bg-brand-blue/5"
        aria-label={isOpen ? "Fechar menu do perfil" : "Abrir menu do perfil"}
      >
        <Avatar className="h-7 w-7">
          <AvatarImage src={user.avatar_url || undefined} alt="" />
          <AvatarFallback><AvatarIcon className="h-4 w-4" /></AvatarFallback>
        </Avatar>
        <span className="hidden font-semibold sm:inline">{firstName}</span>
        <ChevronDown
          className={`h-4 w-4 text-slate-500 transition-transform ${isOpen ? "rotate-180" : ""}`}
        />
      </Button>

      {typeof document !== "undefined" &&
        createPortal(menuPanel, document.body)}
    </>
  );
}

import type { RefObject } from "react";
import { Link } from "react-router-dom";
import { Settings } from "lucide-react";
import type { Notification } from "@/types/notification";
import { NOTIFICATIONS_MENU_WIDTH } from "./notificationMenuConfig";
import { NotificationsPanelContent } from "./NotificationsPanelContent";

interface NotificationsPanelProps {
  loading: boolean;
  menuRef: RefObject<HTMLDivElement>;
  notifications: Notification[];
  position: { left: number; top: number };
  settingsPath: string;
  unreadCount: number;
  onClose: () => void;
  onMarkAllAsRead: () => void;
  onOpenNotification: (notification: Notification) => void;
}

export function NotificationsPanel({
  loading,
  menuRef,
  notifications,
  position,
  settingsPath,
  unreadCount,
  onClose,
  onMarkAllAsRead,
  onOpenNotification,
}: NotificationsPanelProps) {
  return (
    <div
      id="notifications-panel"
      ref={menuRef}
      role="region"
      aria-label="Notificações"
      style={{
        position: "absolute",
        top: position.top,
        left: position.left,
        width: NOTIFICATIONS_MENU_WIDTH,
      }}
      className="z-[100] overflow-hidden rounded-xl border border-slate-200 bg-white shadow-xl"
    >
      <div
        className="h-1 bg-gradient-to-r from-brand-blue via-sky-300 to-brand-orange"
        aria-hidden
      />

      <div className="flex items-center justify-between gap-3 border-b border-slate-100 px-4 py-3.5">
        <div>
          <h2 className="text-base font-bold text-brand-dark">Notificações</h2>
          {unreadCount > 0 && (
            <p className="text-xs text-slate-500">
              {unreadCount} não lida{unreadCount > 1 ? "s" : ""}
            </p>
          )}
        </div>

        {unreadCount > 0 && (
          <button
            type="button"
            onClick={onMarkAllAsRead}
            className="shrink-0 text-xs font-semibold text-brand-blue transition hover:text-brand-blue/80"
          >
            Marcar todas como lidas
          </button>
        )}
      </div>

      <div className="max-h-[min(24rem,70dvh)] overflow-y-auto p-2">
        <NotificationsPanelContent
          loading={loading}
          notifications={notifications}
          onOpenNotification={onOpenNotification}
        />
      </div>

      <div className="border-t border-slate-100 p-2">
        <Link
          to={settingsPath}
          onClick={onClose}
          className="flex items-center gap-2 rounded-lg px-3 py-2.5 text-sm font-medium text-slate-600 transition hover:bg-brand-blue/8 hover:text-brand-blue"
        >
          <Settings className="h-4 w-4" />
          Preferências de notificação
        </Link>
      </div>
    </div>
  );
}

import { useRef, useState, type KeyboardEvent } from "react";
import { Link } from "react-router-dom";
import { ArrowRight, Footprints, UsersRound } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import type { ProductWithImages } from "@/types/product-detail";
import type { SharedPurchaseSide } from "@/types/shared-purchase";

interface SharedPurchaseOfferProps {
  product: ProductWithImages;
  onCreate: (side: SharedPurchaseSide) => boolean | Promise<boolean>;
}

const money = (value: number) =>
  value.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

const normalizeFootType = (footType?: string) =>
  String(footType || "")
    .trim()
    .toLocaleLowerCase("pt-BR");

export function SharedPurchaseOffer({
  product,
  onCreate,
}: SharedPurchaseOfferProps) {
  const [open, setOpen] = useState(false);
  const [side, setSide] = useState<SharedPurchaseSide>("left");
  const [creating, setCreating] = useState(false);
  const radioRefs = useRef<Array<HTMLButtonElement | null>>([]);

  const normalizedFootType = normalizeFootType(product.foot_type);
  const isPair = ["pair", "par", "both", "par completo"].includes(normalizedFootType);

  if (!isPair) return null;

  const handleCreate = async () => {
    if (creating) return;
    setCreating(true);
    try {
      const created = await onCreate(side);
      if (created) setOpen(false);
    } finally {
      setCreating(false);
    }
  };

  const handleRadioKeyDown = (
    event: KeyboardEvent<HTMLButtonElement>,
    index: number,
  ) => {
    const sides: SharedPurchaseSide[] = ["left", "right"];
    let nextIndex: number | null = null;
    if (["ArrowRight", "ArrowDown"].includes(event.key)) {
      nextIndex = (index + 1) % sides.length;
    } else if (["ArrowLeft", "ArrowUp"].includes(event.key)) {
      nextIndex = (index - 1 + sides.length) % sides.length;
    } else if (event.key === "Home") {
      nextIndex = 0;
    } else if (event.key === "End") {
      nextIndex = sides.length - 1;
    }
    if (nextIndex === null) return;
    event.preventDefault();
    setSide(sides[nextIndex]);
    radioRefs.current[nextIndex]?.focus();
  };

  return (
    <section className="rounded-lg border border-brand-orange/30 bg-brand-orange/[0.06] p-3">
      <div className="flex items-center gap-3">
        <span className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-white text-brand-orange shadow-sm">
          <UsersRound className="h-4 w-4" />
        </span>
        <div className="min-w-0 flex-1">
          <p className="text-xs font-bold uppercase tracking-[0.12em] text-brand-orange">
            Compra compartilhada
          </p>
          <p className="mt-0.5 text-sm font-semibold text-slate-800">
            Leve apenas um pé por{" "}
            <strong className="text-brand-blue">{money(Number(product.price) / 2)}</strong>
          </p>
        </div>
      </div>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogTrigger asChild>
          <Button className="mt-3 w-full bg-brand-orange text-white hover:bg-brand-orange/90">
            Escolher meu pé
            <ArrowRight className="h-4 w-4" />
          </Button>
        </DialogTrigger>
        <DialogContent className="border-slate-200 sm:max-w-lg">
          <DialogHeader>
            <DialogTitle>Qual pé você precisa?</DialogTitle>
            <DialogDescription>
              O outro lado ficará disponível no mural por até 48 horas.
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-3 sm:grid-cols-2" role="radiogroup" aria-label="Pé desejado">
            {(["left", "right"] as SharedPurchaseSide[]).map((value, index) => {
              const selected = side === value;
              const label = value === "left" ? "Pé esquerdo" : "Pé direito";
              return (
                <button
                  ref={(element) => {
                    radioRefs.current[index] = element;
                  }}
                  key={value}
                  type="button"
                  role="radio"
                  aria-checked={selected}
                  tabIndex={selected ? 0 : -1}
                  onClick={() => setSide(value)}
                  onKeyDown={(event) => handleRadioKeyDown(event, index)}
                  className={`rounded-lg border p-4 text-left transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-blue ${
                    selected
                      ? "border-brand-blue bg-brand-blue/5 shadow-sm"
                      : "border-slate-200 hover:border-brand-blue/30"
                  }`}
                >
                  <Footprints className={`h-5 w-5 ${selected ? "text-brand-blue" : "text-slate-500"}`} />
                  <span className="mt-3 block font-bold text-slate-900">{label}</span>
                  <span className="mt-1 block text-sm text-slate-600">
                    Tamanho {product.size || "informado no anúncio"}
                  </span>
                </button>
              );
            })}
          </div>

          <div className="rounded-lg border border-sky-100 bg-sky-50 p-4 text-sm leading-6 text-slate-600">
            Você ainda não será cobrado. A compra só avança depois que outra
            pessoa reservar o lado complementar.
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setOpen(false)} disabled={creating}>
              Cancelar
            </Button>
            <Button onClick={handleCreate} disabled={creating} aria-busy={creating} className="bg-brand-orange text-white hover:bg-orange-800">
              {creating ? "Publicando..." : "Publicar reserva"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Button asChild variant="link" className="mt-1 h-auto w-full py-1 text-xs text-brand-blue hover:text-brand-blue">
        <Link to={`/shared-purchases?product=${product.id}`}>
          Ver quem já procura este modelo
        </Link>
      </Button>
    </section>
  );
}

import { Minus, Plus } from "lucide-react";

interface ProductQuantitySelectorProps {
  maxQuantity: number;
  productName: string;
  selectedQuantity: number;
  onUpdateQuantity: (quantity: number) => void;
}

