import { useEffect, useId, useRef, useState } from "react";
import { Camera, Check, CheckCircle2, ImagePlus, Loader2, Trash2, X } from "lucide-react";
import { useAuth } from "@/contexts/AuthContext";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { readApiError } from "@/lib/apiErrors";

const MAX_SIZE = 5 * 1024 * 1024;
const IMAGE_TYPES = ["image/jpeg", "image/png", "image/webp"];

export function AvatarEditor() {
  const { user, setUser, token } = useAuth();
  const inputId = useId();
  const inputRef = useRef<HTMLInputElement>(null);
  const chooseButtonRef = useRef<HTMLButtonElement>(null);
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string>();
  const [action, setAction] = useState<"upload" | "remove" | null>(null);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const busy = action !== null;

  useEffect(() => {
    if (!file) {
      setPreview(undefined);
      return;
    }
    const url = URL.createObjectURL(file);
    setPreview(url);
    return () => URL.revokeObjectURL(url);
  }, [file]);

  if (!user) return null;

  const cancelSelection = () => {
    chooseButtonRef.current?.focus();
    setFile(null);
    setError("");
    setSuccess("");
  };

  const changeAvatar = async (remove = false) => {
    if (!remove && !file) return;
    setAction(remove ? "remove" : "upload");
    setError("");
    setSuccess("");
    try {
      if (!token) throw new Error("Entre na sua conta para alterar a foto.");
      const body = new FormData();
      if (file) body.append("image", file);
      const response = await fetch("/api/users/me/avatar", {
        method: remove ? "DELETE" : "PUT",
        headers: { Authorization: `Bearer ${token}` },
        ...(remove ? {} : { body }),
      });
      if (!response.ok) {
        throw new Error(await readApiError(response, "Não foi possível alterar sua foto."));
      }
      const data: { avatar_url: string | null } = await response.json();
      setUser({ ...user, avatar_url: data.avatar_url });
      setFile(null);
      setSuccess(remove ? "Foto removida." : "Foto de perfil atualizada.");
    } catch (requestError) {
      setError(requestError instanceof Error ? requestError.message : "Não foi possível alterar sua foto.");
    } finally {
      setAction(null);
    }
  };

  const initials = user.name.trim().split(/\s+/).slice(0, 2).map((name) => name[0]).join("").toUpperCase();

  return (
    <Card className="overflow-hidden rounded-xl border-slate-200 bg-white shadow-sm" aria-busy={busy} aria-labelledby={`${inputId}-title`}>
      <CardContent className="p-5 sm:p-6">
        <h2 id={`${inputId}-title`} className="mb-5 text-sm font-semibold text-slate-900">Foto de perfil</h2>
        <div className="flex items-center gap-4">
          <div className="relative shrink-0">
            <Avatar className="h-20 w-20 border-4 border-white ring-1 ring-slate-200">
              <AvatarImage src={preview || user.avatar_url || undefined} className="object-cover" alt={file ? "Prévia da nova foto de perfil" : `Foto de perfil de ${user.name}`} />
              <AvatarFallback className="bg-brand-blue/5 text-xl font-semibold text-brand-blue">{initials}</AvatarFallback>
            </Avatar>
            <span className="absolute -bottom-0.5 -right-0.5 grid h-7 w-7 place-items-center rounded-full border-2 border-white bg-brand-blue text-white" aria-hidden="true">
              <Camera className="h-3.5 w-3.5" />
            </span>
          </div>
          <div className="min-w-0">
            <p className="break-words text-base font-semibold leading-snug text-slate-900">{user.name}</p>
            <p className="mt-1 break-all text-xs leading-relaxed text-slate-500">{user.email}</p>
            <span className="mt-2 inline-flex rounded-full bg-slate-100 px-2.5 py-1 text-xs font-medium text-slate-600">
              {user.type === "seller" ? "Conta de vendedor" : "Conta de comprador"}
            </span>
          </div>
        </div>

        <input ref={inputRef} id={inputId} type="file" accept="image/jpeg,image/png,image/webp" className="sr-only" tabIndex={-1}
          aria-label="Escolher foto de perfil" disabled={busy} aria-describedby={`${inputId}-hint`}
          onChange={(event) => {
            const selected = event.target.files?.[0];
            event.target.value = "";
            if (!selected) return;
            setError("");
            setSuccess("");
            if (!IMAGE_TYPES.includes(selected.type) || selected.size === 0 || selected.size > MAX_SIZE) {
              setError("Escolha uma imagem JPG, PNG ou WebP de até 5 MB.");
              setFile(null);
              return;
            }
            setFile(selected);
          }} />
        <Button ref={chooseButtonRef} type="button" variant="outline" disabled={busy} aria-describedby={`${inputId}-hint`} onClick={() => inputRef.current?.click()}
          className="mt-5 h-11 w-full gap-2 border-slate-200 bg-white font-medium text-slate-700 hover:border-brand-blue/40 hover:bg-brand-blue/5 hover:text-brand-blue">
          <ImagePlus className="h-4 w-4" aria-hidden="true" />
          {file ? "Escolher outra foto" : user.avatar_url ? "Alterar foto" : "Adicionar foto"}
        </Button>
        <p id={`${inputId}-hint`} className="mt-2.5 text-center text-xs leading-relaxed text-slate-500">JPG, PNG ou WebP. Até 5 MB.</p>

        {file && (
          <div className="mt-4 rounded-lg border border-brand-blue/15 bg-brand-blue/[0.03] p-3">
            <p className="text-xs font-semibold text-brand-blue">Nova foto selecionada</p>
            <p className="mt-1 break-all text-xs leading-relaxed text-slate-600" title={file.name}>Selecionada: {file.name}</p>
            <div className="mt-3 flex gap-2">
              <Button type="button" disabled={busy} onClick={() => changeAvatar()} className="h-11 flex-1 gap-1.5 bg-brand-blue text-white hover:bg-brand-blue/90">
                {action === "upload" ? <Loader2 className="h-4 w-4 animate-spin motion-reduce:animate-none" aria-hidden="true" /> : <Check className="h-4 w-4" aria-hidden="true" />}
                {action === "upload" ? "Salvando…" : "Salvar foto"}
              </Button>
              <Button type="button" variant="outline" disabled={busy} onClick={cancelSelection} className="h-11 w-11 shrink-0 p-0" aria-label="Cancelar seleção da foto">
                <X className="h-4 w-4" aria-hidden="true" />
              </Button>
            </div>
            <p className="mt-2 text-xs leading-relaxed text-slate-500">Confirme para atualizar sua foto.</p>
          </div>
        )}

        {!file && user.avatar_url && (
          <Button type="button" variant="ghost" disabled={busy} onClick={() => changeAvatar(true)} className="mt-1 h-11 w-full gap-2 text-sm text-slate-500 hover:bg-red-50 hover:text-red-700">
            {action === "remove" ? <Loader2 className="h-4 w-4 animate-spin motion-reduce:animate-none" aria-hidden="true" /> : <Trash2 className="h-3.5 w-3.5" aria-hidden="true" />}
            {action === "remove" ? "Removendo…" : "Remover foto"}
          </Button>
        )}
        {error && <p role="alert" className="mt-3 rounded-lg bg-red-50 p-3 text-sm leading-relaxed text-red-700">{error}</p>}
        <div role="status" aria-live="polite">
          {success && <p className="mt-3 flex items-start gap-2 text-sm leading-relaxed text-emerald-700"><CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0" aria-hidden="true" />{success}</p>}
        </div>
        <p className="mt-5 border-t border-slate-100 pt-4 text-xs leading-relaxed text-slate-500">A foto é salva separadamente dos dados do perfil.</p>
      </CardContent>
    </Card>
  );
}

import { useId, useRef, useState } from "react";
import { ChevronDown, RotateCcw, Package } from "lucide-react";
import { SellerOrderMainInfo } from "./SellerOrderMainInfo";
import { SellerOrderActions } from "./SellerOrderActions";
import { SellerOrderDetails } from "./SellerOrderDetails";
import { getProductImageSrc } from "@/lib/productImages";
import { Card } from "@/components/ui/card";
import type { SellerOrder } from "@/types/seller-dashboard";
import {
  sellerOrderStatusMeta,
  getNextSellerOrderStatus,
  getSellerOrderItems,
  getSellerOrderPlatformFee,
  getSellerOrderProductSummary,
  getSellerOrderSplitStatus,
  getSellerOrderTotal,
} from "./sellerOrdersUtils";
import type {
  PostPurchaseRequest,
  PostPurchaseRequestStatus,
} from "@/types/post-purchase-request";

interface SellerOrderCardProps {
  order: SellerOrder;
  postPurchaseRequests: PostPurchaseRequest[];
  sellerId: number | null;
  updating: boolean;
  updatingRequestId: number | null;
  onAdvance: (order: SellerOrder) => void;
  onUpdateRequestStatus: (
    requestId: number,
    status: PostPurchaseRequestStatus,
    sellerResponse?: string,
  ) => void;
}

export function SellerOrderCard({
  order,
  postPurchaseRequests,
  sellerId,
  updating,
  updatingRequestId,
  onAdvance,
  onUpdateRequestStatus,
}: SellerOrderCardProps) {
  const [detailsOpen, setDetailsOpen] = useState(false);
  const detailsId = useId();
  const titleId = useId();
  const requestsRef = useRef<HTMLDivElement>(null);
  const detailsButtonRef = useRef<HTMLButtonElement>(null);
  const closeDetails = () => {
    setDetailsOpen(false);
    requestAnimationFrame(() => detailsButtonRef.current?.focus());
  };
  const openRequests = () => {
    setDetailsOpen(true);
    requestAnimationFrame(() => {
      requestsRef.current?.scrollIntoView?.({ block: "nearest" });
      requestsRef.current?.focus({ preventScroll: true });
    });
  };
  const items = getSellerOrderItems(order, sellerId);
  const total = getSellerOrderTotal(order, sellerId);
  const platformFee = getSellerOrderPlatformFee(order, sellerId);
  const splitStatus = getSellerOrderSplitStatus(order, sellerId);
  const productSummary = getSellerOrderProductSummary(
    { ...order, items: items.slice(0, 1) },
    sellerId,
  );
  const shipment = order.shipments?.find(
    (entry) => entry.seller_id === sellerId,
  );
  const ownStatus = shipment
    ? shipment.status === "pending"
      ? "paid"
      : shipment.status
    : order.status;
  const displayOrder = { ...order, status: ownStatus };
  const pairReady = items.every(
    (item) =>
      !item.shared_purchase || item.shared_purchase.status === "completed",
  );
  const canAdvance = pairReady && Boolean(getNextSellerOrderStatus(ownStatus));

  const statusMeta = sellerOrderStatusMeta[ownStatus];

  return (
    <article aria-labelledby={titleId}>
      <Card className="overflow-clip rounded-2xl border-brand-blue/25 shadow-sm transition-shadow hover:shadow-md motion-reduce:transition-none">
        <div>
          <header
            className={`flex flex-wrap items-center justify-between gap-3 border-b border-brand-blue/10 px-4 py-3 sm:px-5 ${detailsOpen ? "sticky top-[var(--site-header-height,72px)] z-20 bg-white shadow-sm" : "bg-brand-blue/[0.04]"}`}
          >
            <h2
              id={titleId}
              className="flex items-center gap-2 text-sm font-bold text-brand-blue"
            >
              <Package className="h-4 w-4" aria-hidden="true" />
              Pedido #{order.id}
            </h2>
            <span
              className={`inline-flex items-center gap-1.5 rounded-full border border-current/10 px-3 py-1 text-xs font-semibold ${statusMeta.className}`}
            >
              <span
                className="h-1.5 w-1.5 rounded-full bg-current"
                aria-hidden="true"
              />
              {statusMeta.label}
            </span>
          </header>
          <div className="px-4 py-4 sm:px-5 sm:py-5">
            <SellerOrderMainInfo
              itemCount={items.length}
              order={displayOrder}
              productSummary={productSummary}
              total={total}
              productImage={getProductImageSrc(items[0]?.product, "")}
            />
            {!pairReady && (
              <p
                role="status"
                className="mt-3 text-sm leading-6 text-amber-800"
              >
                Aguardando confirmação dos dois pagamentos para liberar o envio.
              </p>
            )}
          </div>
          <div className="flex flex-col gap-3 border-t border-brand-blue/10 bg-slate-50/70 px-4 py-3 sm:flex-row sm:items-center sm:justify-between sm:px-5">
            <div className="flex flex-wrap items-center gap-3">
              <button
                ref={detailsButtonRef}
                type="button"
                aria-expanded={detailsOpen}
                aria-controls={detailsId}
                aria-label={`${detailsOpen ? "Ocultar" : "Ver"} detalhes do pedido #${order.id}`}
                onClick={() => setDetailsOpen(!detailsOpen)}
                className="inline-flex min-h-11 items-center gap-2 rounded-lg px-2 text-sm font-semibold text-brand-blue hover:bg-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-blue"
              >
                {detailsOpen ? "Ocultar detalhes" : "Ver detalhes"}
                <ChevronDown
                  className={`h-4 w-4 transition-transform motion-reduce:transition-none ${detailsOpen ? "rotate-180" : ""}`}
                  aria-hidden="true"
                />
              </button>
              {postPurchaseRequests.length > 0 && (
                <button
                  type="button"
                  onClick={openRequests}
                  aria-controls={detailsId}
                  className="inline-flex min-h-11 items-center gap-2 rounded-lg border border-brand-orange/15 bg-brand-orange/5 px-3 text-sm font-medium text-brand-orange hover:bg-brand-orange/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-orange"
                >
                  <RotateCcw className="h-4 w-4" aria-hidden="true" />
                  {postPurchaseRequests.length}{" "}
                  {postPurchaseRequests.length === 1
                    ? "solicitação pós-compra"
                    : "solicitações pós-compra"}
                </button>
              )}
            </div>
            <SellerOrderActions
              compact
              order={displayOrder}
              canAdvance={canAdvance}
              updating={updating}
              onAdvance={onAdvance}
            />
          </div>
          <div
            id={detailsId}
            hidden={!detailsOpen}
            className="border-t-2 border-brand-blue/15 bg-slate-100/70 p-4 sm:p-6"
          >
            <SellerOrderDetails
              order={displayOrder}
              items={items}
              shipment={shipment}
              platformFee={platformFee}
              splitStatus={splitStatus}
              requests={postPurchaseRequests}
              updatingRequestId={updatingRequestId}
              requestsRef={requestsRef}
              onClose={closeDetails}
              onUpdateRequestStatus={onUpdateRequestStatus}
            />
          </div>
        </div>
      </Card>
    </article>
  );
}

import type { ReactNode, RefObject } from "react";
import { Banknote, Package, Truck, ChevronUp } from "lucide-react";
import type { LucideIcon } from "lucide-react";
import type { SellerOrder } from "@/types/seller-dashboard";
import type {
  PostPurchaseRequest,
  PostPurchaseRequestStatus,
} from "@/types/post-purchase-request";
import {
  getProductImageSrc,
  PRODUCT_PLACEHOLDER_IMAGE,
} from "@/lib/productImages";
import { SellerOrderPaymentInfo } from "./SellerOrderPaymentInfo";
import {
  SellerOrderCustomerInfo,
  SellerOrderTimeline,
  SellerOrderTrackingInfo,
} from "./SellerOrderDeliveryInfo";
import { SellerOrderSharedPurchaseInfo } from "./SellerOrderSharedPurchaseInfo";
import { SellerOrderRequestsPanel } from "./SellerOrderRequestsPanel";

type Props = {
  order: SellerOrder;
  items: SellerOrder["items"];
  shipment?: NonNullable<SellerOrder["shipments"]>[number];
  platformFee: number;
  splitStatus: string;
  requests: PostPurchaseRequest[];
  updatingRequestId: number | null;
  requestsRef: RefObject<HTMLDivElement>;
  onClose: () => void;
  onUpdateRequestStatus: (
    id: number,
    status: PostPurchaseRequestStatus,
    response?: string,
  ) => void;
};

function DetailSection({
  title,
  icon: Icon,
  children,
}: {
  title: string;
  icon: LucideIcon;
  children: ReactNode;
}) {
  return (
    <section className="rounded-xl border border-slate-200 bg-white p-4 sm:p-5">
      <h4 className="mb-4 flex items-center gap-3 border-b border-slate-100 pb-3 text-base font-semibold text-slate-900">
        <span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-brand-blue/5 text-brand-blue">
          <Icon className="h-4 w-4" aria-hidden="true" />
        </span>
        {title}
      </h4>
      {children}
    </section>
  );
}

export function SellerOrderDetails({
  order,
  items,
  shipment,
  platformFee,
  splitStatus,
  requests,
  updatingRequestId,
  requestsRef,
  onClose,
  onUpdateRequestStatus,
}: Props) {
  return (
    <div className="space-y-5">
      <div className="border-l-2 border-brand-blue pl-3">
        <h3 className="text-base font-bold text-slate-900">
          Detalhes do pedido #{order.id}
        </h3>
      </div>
      <div
        className={`grid items-start gap-5 ${items.length > 1 ? "lg:grid-cols-[minmax(0,1.3fr)_minmax(0,1fr)]" : "grid-cols-1"}`}
      >
        {items.length > 1 && (
          <DetailSection title="Itens do pedido" icon={Package}>
            <ul className="divide-y divide-slate-100">
              {items.map((item) => {
                const image = getProductImageSrc(item.product, "");
                return (
                  <li
                    key={item.id}
                    className="flex items-start gap-3 py-4 first:pt-0 last:pb-0"
                  >
                    <span className="grid h-14 w-14 shrink-0 place-items-center overflow-hidden rounded-lg border border-slate-200 bg-slate-50 text-brand-blue">
                      {image ? (
                        <img
                          src={image}
                          alt=""
                          width={56}
                          height={56}
                          loading="lazy"
                          className="h-full w-full object-cover"
                          onError={(event) => {
                            event.currentTarget.onerror = null;
                            event.currentTarget.src = PRODUCT_PLACEHOLDER_IMAGE;
                          }}
                        />
                      ) : (
                        <Package className="h-5 w-5" aria-hidden="true" />
                      )}
                    </span>
                    <div className="min-w-0">
                      <p className="text-sm font-semibold leading-6 text-slate-900">
                        {item.product?.name || `Produto #${item.product_id}`}
                      </p>
                      <div className="mt-1 flex flex-wrap gap-x-3 gap-y-1 text-sm leading-6 text-slate-600">
                        <span>Quantidade: {item.quantity}</span>
                        {item.shared_side && (
                          <span className="font-medium text-brand-blue">
                            {item.shared_side === "left"
                              ? "Pé esquerdo"
                              : "Pé direito"}
                          </span>
                        )}
                      </div>
                    </div>
                  </li>
                );
              })}
            </ul>
          </DetailSection>
        )}
        <DetailSection title="Valores e repasse" icon={Banknote}>
          <SellerOrderPaymentInfo
            platformFee={platformFee}
            splitStatus={splitStatus}
          />
        </DetailSection>
      </div>
      <DetailSection title="Cliente e entrega" icon={Truck}>
        <SellerOrderCustomerInfo order={order} compact />
        <SellerOrderTimeline status={order.status} />
        {shipment && <SellerOrderTrackingInfo shipment={shipment} />}
      </DetailSection>
      <SellerOrderSharedPurchaseInfo items={items} />
      {requests.length > 0 && (
        <div
          ref={requestsRef}
          role="region"
          aria-label={`Solicitações do pedido #${order.id}`}
          tabIndex={-1}
          className="scroll-mt-28 rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-brand-orange"
        >
          <SellerOrderRequestsPanel
            requests={requests}
            updatingId={updatingRequestId}
            onUpdateStatus={onUpdateRequestStatus}
          />
        </div>
      )}
      <div className="flex justify-end border-t border-slate-200 pt-4">
        <button
          type="button"
          onClick={onClose}
          aria-label={`Recolher detalhes do pedido #${order.id}`}
          className="inline-flex min-h-11 items-center gap-2 rounded-xl px-3 text-sm font-semibold text-brand-blue hover:bg-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-blue"
        >
          Recolher detalhes
          <ChevronUp className="h-4 w-4" aria-hidden="true" />
        </button>
      </div>
    </div>
  );
}

import { Search } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import type { SellerOrderStatus } from "@/types/seller-dashboard";

type FilterOption = {
  value: "all" | SellerOrderStatus;
  label: string;
  count: number;
};

interface SellerOrdersToolbarProps {
  filter: "all" | SellerOrderStatus;
  filterOptions: readonly FilterOption[];
  query: string;
  resultCount: number;
  onFilterChange: (filter: "all" | SellerOrderStatus) => void;
  onQueryChange: (query: string) => void;
}

export function SellerOrdersToolbar({
  filter,
  filterOptions,
  query,
  resultCount,
  onFilterChange,
  onQueryChange,
}: SellerOrdersToolbarProps) {
  return (
    <div className="space-y-4 bg-white px-4 pt-5 pb-1 sm:px-6">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
