          <Button
            key={option.value}
            variant="ghost"
            onClick={() => onFilterChange(option.value)}
            aria-pressed={filter === option.value}
            className={`min-h-12 gap-2 rounded-none border-b-2 px-1 shadow-none ${filter === option.value ? "border-brand-blue bg-transparent text-brand-blue hover:bg-brand-blue/5 hover:text-brand-blue" : "border-transparent bg-transparent text-slate-600 hover:bg-slate-50"}`}
          >
            {option.label}
            <span
              className={`rounded-md px-1.5 py-0.5 text-xs ${filter === option.value ? "bg-brand-blue/10 text-brand-blue" : "bg-slate-100 text-slate-600"}`}
