import type React from "react";
import {
  AlertCircle,
  Building2,
  CheckCircle2,
  FileText,
  Loader2,
  MapPin,
  Phone,
  Save,
  Store,
  UserRound,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { FormErrorSummary } from "@/components/ui/FormErrorSummary";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import type { FormErrorItem } from "@/lib/formA11y";
import type {
  SellerEditForm,
  SellerEditSection,
} from "./sellerEditProfileConfig";
import { SellerEditProfileField } from "./SellerEditProfileField";

interface SellerEditProfileFormProps {
  cardDescription: string;
  cardEyebrow: string;
  cardTitle: string;
  error: string | null;
  form: SellerEditForm;
  loading: boolean;
  section: SellerEditSection;
  success: string | null;
  summaryErrors: FormErrorItem[];
  onCancel: () => void;
  onChange: (
    event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>,
  ) => void;
  onSubmit: (event: React.FormEvent<HTMLFormElement>) => void;
}

const fieldClass = "h-11 border-slate-200 bg-white shadow-sm";

export function SellerEditProfileForm({
  cardDescription,
  cardEyebrow,
  cardTitle,
  error,
  form,
  loading,
  section,
  success,
  summaryErrors,
  onCancel,
  onChange,
  onSubmit,
}: SellerEditProfileFormProps) {
  return (
    <Card className="min-w-0 overflow-hidden rounded-xl border-slate-200 bg-white shadow-sm">
      <CardHeader className="border-b border-slate-100 bg-slate-50/60">
        <p className="text-xs font-medium text-slate-500">
          {cardEyebrow}
        </p>
        <h2 className="text-xl font-bold text-slate-900">{cardTitle}</h2>
        <p className="text-sm text-slate-500">{cardDescription}</p>
      </CardHeader>
      <CardContent className="p-card">
        <form onSubmit={onSubmit} aria-busy={loading} className="space-y-6" noValidate>
          <FormErrorSummary errors={summaryErrors} />
          {section === "personal" ? (
            <SellerPersonalFields form={form} onChange={onChange} />
          ) : (
            <SellerStoreFields form={form} onChange={onChange} />
          )}
          <SellerEditProfileAlerts error={error} success={success} />
          <SellerEditProfileActions loading={loading} onCancel={onCancel} />
        </form>
      </CardContent>
    </Card>
  );
}

function SellerPersonalFields({
  form,
  onChange,
}: Pick<SellerEditProfileFormProps, "form" | "onChange">) {
  return (
    <fieldset className="space-y-5">
      <legend className="mb-3 text-sm font-bold uppercase tracking-wider text-slate-500">
        Responsável
      </legend>
      <div className="grid gap-5 md:grid-cols-2">
        <SellerEditProfileField label="Nome do responsável" id="name" icon={UserRound}>
          <Input id="name" name="name" value={form.name} onChange={onChange} required autoComplete="name" className={fieldClass} />
        </SellerEditProfileField>
        <SellerEditProfileField label="CNPJ" id="cnpj" icon={Building2}>
          <Input id="cnpj" name="cnpj" value={form.cnpj} onChange={onChange} className={fieldClass} />
        </SellerEditProfileField>
        <SellerEditProfileField label="Telefone" id="phone" icon={Phone}>
          <Input id="phone" name="phone" value={form.phone} onChange={onChange} autoComplete="tel" placeholder="(99) 99999-9999" className={fieldClass} />
        </SellerEditProfileField>
        <SellerEditProfileField label="E-mail da conta" id="email" icon={UserRound} hint="O e-mail é alterado nas configurações da conta.">
          <Input id="email" name="email" value={form.email} readOnly className="h-11 border-slate-200 bg-slate-100 text-slate-500" />
        </SellerEditProfileField>
      </div>
    </fieldset>
  );
}

function SellerStoreFields({
  form,
  onChange,
}: Pick<SellerEditProfileFormProps, "form" | "onChange">) {
  return (
    <>
      <fieldset className="space-y-5">
        <legend className="mb-3 text-sm font-bold uppercase tracking-wider text-slate-500">
          Vitrine pública
        </legend>
        <div className="grid gap-5 md:grid-cols-2">
          <SellerEditProfileField label="Nome da loja" id="store_name" icon={Store}>
            <Input id="store_name" name="store_name" value={form.store_name} onChange={onChange} required className={fieldClass} />
          </SellerEditProfileField>
          <SellerEditProfileField label="CEP de origem" id="cep" icon={MapPin}>
            <Input id="cep" name="cep" value={form.cep} onChange={onChange} autoComplete="postal-code" placeholder="00000-000" className={fieldClass} />
          </SellerEditProfileField>
          <div className="md:col-span-2">
            <SellerEditProfileField label="Endereço de origem" id="address" icon={MapPin}>
              <Input id="address" name="address" value={form.address} onChange={onChange} autoComplete="street-address" className={fieldClass} />
            </SellerEditProfileField>
          </div>
          <SellerEditProfileField label="Cidade" id="city" icon={MapPin}>
            <Input id="city" name="city" value={form.city} onChange={onChange} className={fieldClass} />
          </SellerEditProfileField>
          <SellerEditProfileField label="Estado" id="state" icon={MapPin}>
            <Input id="state" name="state" value={form.state} onChange={onChange} maxLength={2} className={fieldClass} />
          </SellerEditProfileField>
        </div>
      </fieldset>

      <div className="space-y-2 border-t border-slate-100 pt-6">
        <label htmlFor="description" className="flex items-center gap-2 text-sm font-semibold text-slate-700">
          <FileText className="h-4 w-4 text-brand-blue" />
          Descrição da loja
        </label>
        <Textarea id="description" name="description" value={form.description} onChange={onChange} rows={5} placeholder="Conte o que torna sua loja especial..." className="resize-y border-slate-200 bg-white shadow-sm" />
      </div>
    </>
  );
}

function SellerEditProfileAlerts({
  error,
  success,
}: Pick<SellerEditProfileFormProps, "error" | "success">) {
  return (
    <>
      {error && (
        <div role="alert" className="flex items-start gap-2 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700">
          <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
          {error}
        </div>
      )}
      {success && (
        <div role="status" className="flex items-start gap-2 rounded-lg border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-700">
          <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0" />
          {success}
        </div>
      )}
    </>
  );
}

function SellerEditProfileActions({
  loading,
  onCancel,
}: Pick<SellerEditProfileFormProps, "loading" | "onCancel">) {
  return (
    <div className="flex flex-col-reverse gap-3 border-t border-slate-100 pt-5 sm:flex-row sm:justify-end">
      <Button type="button" variant="outline" onClick={onCancel} disabled={loading}>
        Cancelar
      </Button>
      <Button type="submit" disabled={loading} className="bg-brand-orange font-semibold text-white hover:bg-orange-800">
        {loading ? (
          <>
            <Loader2 className="h-4 w-4 animate-spin" />
            Salvando...
          </>
        ) : (
          <>
            <Save className="h-4 w-4" />
            Salvar alterações
          </>
        )}
      </Button>
    </div>
  );
}

import { Link } from "react-router-dom";
import { Search, UsersRound } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import type { SharedPurchaseReservation } from "@/types/shared-purchase";
import { SharedReservationCard } from "./SharedReservationCard";
import type { SharedPurchaseSideFilter } from "@/hooks/useSharedPurchases";

interface SharedPurchasesListSectionProps {
  highlightedId: string | null;
  loading: boolean;
  query: string;
  reservations: SharedPurchaseReservation[];
  sideFilter: SharedPurchaseSideFilter;
  userName?: string;
  userId?: number;
  onJoin: (reservation: SharedPurchaseReservation) => void;
  onPay: (reservation: SharedPurchaseReservation) => void;
  onQueryChange: (query: string) => void;
  onSideFilterChange: (filter: SharedPurchaseSideFilter) => void;
}

export function SharedPurchasesListSection({
  highlightedId,
  loading,
  query,
  reservations,
  sideFilter,
  userName,
  userId,
  onJoin,
  onPay,
  onQueryChange,
  onSideFilterChange,
}: SharedPurchasesListSectionProps) {
  return (
    <section aria-labelledby="open-reservations-title">
      <div className="mb-5 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <p className="text-xs font-bold uppercase tracking-[0.16em] text-brand-blue">
            Reservas abertas
          </p>
          <h2
            id="open-reservations-title"
            className="mt-1 text-2xl font-bold text-slate-900"
          >
            Pessoas procurando o outro pé
          </h2>
        </div>
        <SharedPurchasesFilters
          query={query}
          sideFilter={sideFilter}
          onQueryChange={onQueryChange}
          onSideFilterChange={onSideFilterChange}
        />
      </div>

      <p role="status" aria-live="polite" className="sr-only">
        {reservations.length} reservas encontradas
      </p>

      {loading ? (
        <div
          role="status"
          className="rounded-lg border border-slate-200 bg-white py-16 text-center text-slate-500"
        >
          Carregando reservas...
        </div>
      ) : reservations.length === 0 ? (
        <SharedPurchasesEmptyState />
      ) : (
        <div className="grid gap-5 lg:grid-cols-2">
          {reservations.map((reservation) => (
            <SharedReservationCard
              key={reservation.id}
              reservation={reservation}
              highlighted={reservation.id === highlightedId}
              ownReservation={Boolean(
                (userId && reservation.creatorUserId === userId) ||
                  (userName && reservation.creatorName === userName),
              )}
              userId={userId}
              onJoin={() => onJoin(reservation)}
              onPay={() => onPay(reservation)}
            />
          ))}
        </div>
      )}
    </section>
  );
}

interface SharedPurchasesFiltersProps {
  query: string;
  sideFilter: SharedPurchaseSideFilter;
  onQueryChange: (query: string) => void;
  onSideFilterChange: (filter: SharedPurchaseSideFilter) => void;
}

function SharedPurchasesFilters({
  query,
  sideFilter,
  onQueryChange,
  onSideFilterChange,
}: SharedPurchasesFiltersProps) {
  return (
    <div className="flex flex-col gap-3 sm:flex-row">
      <div className="relative sm:w-72">
        <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500" />
        <label htmlFor="shared-search" className="sr-only">
          Buscar reservas
        </label>
        <Input
          id="shared-search"
          type="search"
          value={query}
          onChange={(event) => onQueryChange(event.target.value)}
          placeholder="Modelo, marca ou tamanho"
          className="bg-white pl-10"
        />
      </div>
      <div
        className="flex rounded-lg border border-slate-200 bg-white p-1"
        role="group"
        aria-label="Filtrar pelo pé disponível"
      >
        {(["all", "left", "right"] as SharedPurchaseSideFilter[]).map((side) => (
          <button
            key={side}
            type="button"
            onClick={() => onSideFilterChange(side)}
            aria-pressed={sideFilter === side}
            className={`rounded-md px-3 py-2 text-sm font-semibold transition ${
              sideFilter === side
                ? "bg-brand-blue text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {side === "all" ? "Todos" : side === "left" ? "Esquerdo" : "Direito"}
          </button>
        ))}
      </div>
    </div>
  );
}

function SharedPurchasesEmptyState() {
  return (
    <div className="rounded-lg border border-dashed border-slate-300 bg-white p-elevated text-center">
      <UsersRound className="mx-auto h-9 w-9 text-slate-500" />
      <h3 className="mt-3 text-lg font-bold text-slate-900">
        Nenhuma reserva com estes filtros
      </h3>
      <p className="mt-1 text-sm text-slate-500">
        Tente outro modelo ou publique sua escolha na página de um produto.
      </p>
      <Button asChild className="mt-5 bg-brand-orange text-white hover:bg-orange-800">
        <Link to="/shop">Explorar produtos</Link>
      </Button>
    </div>
  );
}

import { MapPin, Home, Building, Star } from "lucide-react";
import type { KeyboardEvent } from "react";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import type { Address } from "@/types/address";

type ShippingAddressCardProps = {
  loading: boolean;
  addresses: Address[];
  selectedAddress: number | null;
  onSelectAddress: (addressId: number) => void;
  onAddAddress: () => void;
};

export default function ShippingAddressCard({
  loading,
  addresses,
  selectedAddress,
  onSelectAddress,
  onAddAddress,
}: ShippingAddressCardProps) {
  const addressIds = addresses.map((address) => address.id);

  const handleAddressKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const keys = ["ArrowDown", "ArrowRight", "ArrowUp", "ArrowLeft", "Home", "End"];
    if (!keys.includes(event.key) || addressIds.length === 0) return;

    event.preventDefault();
    const currentIndex = Math.max(0, addressIds.indexOf(selectedAddress ?? addressIds[0]));
    const lastIndex = addressIds.length - 1;
    const nextIndex =
      event.key === "Home"
        ? 0
        : event.key === "End"
          ? lastIndex
          : event.key === "ArrowDown" || event.key === "ArrowRight"
            ? Math.min(lastIndex, currentIndex + 1)
            : Math.max(0, currentIndex - 1);

    const nextAddressId = addressIds[nextIndex];
    onSelectAddress(nextAddressId);
    requestAnimationFrame(() => {
      document
        .querySelector<HTMLButtonElement>(
          `[data-shipping-address-id="${nextAddressId}"]`,
        )
        ?.focus();
    });
  };

  const getAddressIcon = (type: string) => {
    switch (type) {
      case "home":
        return <Home className="h-5 w-5 text-brand-blue" />;
      case "work":
        return <Building className="h-5 w-5 text-brand-blue" />;
      default:
        return <MapPin className="h-5 w-5 text-brand-blue" />;
    }
  };

  const getTypeLabel = (type: string) => {
    switch (type) {
      case "home":
        return "Casa";
      case "work":
        return "Trabalho";
      default:
        return "outro";
    }
  };

  return (
    <Card className="overflow-hidden rounded-lg border-slate-200 bg-white shadow-sm">
      <div className="h-1.5 bg-gradient-to-r from-brand-blue to-brand-orange" />
      <CardHeader className="border-b border-slate-100">
        <h2 className="flex items-center gap-2 text-2xl font-semibold text-brand-dark">
          <MapPin className="h-6 w-6 text-brand-blue" />
          Endereço de entrega
        </h2>
      </CardHeader>
      <CardContent className="space-y-4">
        {loading ? (
          <div className="text-center text-gray-500">
            Carregando endereços...
          </div>
        ) : addresses.length === 0 ? (
          <div className="space-y-4 text-center">
            <p className="text-gray-700">
              Você ainda não possui endereços cadastrados...
            </p>
            <Button
              className="bg-brand-orange font-semibold text-white hover:bg-orange-800"
              onClick={onAddAddress}
            >
              Adicionar novo endereço
            </Button>
          </div>
        ) : (
          <div
            className="space-y-3"
            role="radiogroup"
            tabIndex={0}
            aria-label="Escolha o endereço de entrega"
            onKeyDown={handleAddressKeyDown}
          >
            {addresses.map((address) => (
              <button
                key={address.id}
                type="button"
                role="radio"
                data-shipping-address-id={address.id}
                aria-checked={selectedAddress === address.id}
                onClick={() => onSelectAddress(address.id)}
                className={`w-full p-4 rounded-lg border-2 text-left cursor-pointer transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-blue focus-visible:ring-offset-2 ${
                  selectedAddress === address.id
                    ? "border-brand-blue bg-brand-blue/5 shadow-md"
                    : "border-slate-200 hover:border-brand-blue/40 hover:bg-slate-50"
                }`}
              >
              <div className="flex items-start justify-between mb-3">
                <div className="flex items-center gap-3">
                  {getAddressIcon(address.address_type)}
                  <div className="flex items-center gap-2">
                    <span className="flex items-center">
                      <span className="font-semibold text-lg m-0 p-0 leading-tight">
                        {address.recipient_name}
                      </span>
                    </span>
                    <span className="flex items-center">
                      <Badge
                        variant={
                          address.address_type === "home"
                            ? "default"
                            : "secondary"
                        }
                        className="ml-1 px-2 py-0.5 text-xs flex items-center"
                      >
                        {getTypeLabel(address.address_type)}
                      </Badge>
                    </span>
                  </div>
                </div>
                {address.is_primary && (
                  <Badge className="bg-green-100 text-green-800 border-green-200">
                    <Star className="h-3 w-3 mr-1" />
                    Padrão
                  </Badge>
                )}
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-1 text-sm mt-2">
                <div>
                  <span className="font-medium">
                    {address.street}, {address.number}
                  </span>
                  {address.complement && (
                    <span className="text-slate-700">
                      {" "}
                      - {address.complement}
                    </span>
                  )}
                  <div className="text-slate-700">
                    {address.district}, {address.city} - {address.state}
                  </div>
                </div>
                <div className="flex flex-col sm:items-end">
                  <span className="font-mono text-base font-semibold text-brand-blue">
                    CEP: {address.zip_code}
                  </span>
                </div>
              </div>
              </button>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import type { KeyboardEvent, ReactNode } from "react";
import { Truck, Clock } from "lucide-react";
import { Card, CardContent, CardHeader } from "@/components/ui/card";

type AggregatedOption = {
  carrier?: string;
  description?: string;
  distanceKm?: number;
  estimateBasis?: string;
  id: string;
  name: string;
  price: number;
  days: string;
  estimatedDateMin?: string;
  estimatedDateMax?: string;
};

type FallbackOption = {
  id: string;
  name: string;
  price: number;
  description: string;
  estimatedDays: string;
  icon: ReactNode;
};

type ShippingMethodCardProps = {
  aggregatedOptions: AggregatedOption[];
  fallbackOptions: FallbackOption[];
  selectedShipping: string;
  onSelectShipping: (optionId: string) => void;
  shippingErrors: string[];
};

export default function ShippingMethodCard({
  aggregatedOptions,
  fallbackOptions,
  selectedShipping,
  onSelectShipping,
  shippingErrors,
}: ShippingMethodCardProps) {
  const visibleOptionIds =
    aggregatedOptions.length > 0
      ? aggregatedOptions.map((option) => option.id)
      : fallbackOptions.map((option) => option.id);

  const handleShippingKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const keys = [
      "ArrowDown",
      "ArrowRight",
      "ArrowUp",
      "ArrowLeft",
      "Home",
      "End",
    ];
    if (!keys.includes(event.key) || visibleOptionIds.length === 0) return;

    event.preventDefault();
    const currentIndex = Math.max(
      0,
      visibleOptionIds.indexOf(selectedShipping),
    );
    const lastIndex = visibleOptionIds.length - 1;
    const nextIndex =
      event.key === "Home"
        ? 0
        : event.key === "End"
          ? lastIndex
          : event.key === "ArrowDown" || event.key === "ArrowRight"
            ? Math.min(lastIndex, currentIndex + 1)
            : Math.max(0, currentIndex - 1);

    const nextOptionId = visibleOptionIds[nextIndex];
    onSelectShipping(nextOptionId);
    requestAnimationFrame(() => {
      document
        .querySelector<HTMLButtonElement>(
          `[data-shipping-option-id="${nextOptionId}"]`,
        )
        ?.focus();
    });
  };

  return (
    <Card className="overflow-hidden rounded-lg border-slate-200 bg-white shadow-sm">
      <div className="h-1.5 bg-gradient-to-r from-brand-orange to-brand-blue" />
      <CardHeader className="border-b border-slate-100">
        <h2 className="flex items-center gap-2 text-2xl font-semibold text-brand-dark">
          <Truck className="h-6 w-6 text-brand-orange" />
          Método de entrega
        </h2>
      </CardHeader>
      <CardContent className="space-y-4">
        {aggregatedOptions.length > 0 ? (
          <div
            className="space-y-3"
            role="radiogroup"
            tabIndex={0}
            aria-label="Escolha o método de entrega"
            onKeyDown={handleShippingKeyDown}
          >
            {shippingErrors && shippingErrors.length > 0 && (
              <div className="bg-yellow-50 border-l-4 border-yellow-400 p-3 rounded mb-2">
                <div className="font-semibold text-yellow-800">
                  Problemas encontrados ao calcular frete:
                </div>
                <ul className="text-sm text-yellow-700 list-disc ml-5">
                  {shippingErrors.map((err, i) => (
                    <li key={i}>{err}</li>
                  ))}
                </ul>
              </div>
            )}
            {aggregatedOptions.map((opt) => (
              <button
                key={opt.id}
                type="button"
                role="radio"
                aria-label={opt.name}
                data-shipping-option-id={opt.id}
                aria-checked={selectedShipping === opt.id}
                onClick={() => {
                  onSelectShipping(opt.id);
                }}
                className={`w-full p-4 rounded-lg border-2 text-left cursor-pointer transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-orange focus-visible:ring-offset-2 ${
                  selectedShipping === opt.id
                    ? "border-brand-orange bg-brand-orange/5 shadow-md"
                    : "border-slate-200 hover:border-brand-orange/40 hover:bg-slate-50"
                }`}
              >
                <div className="flex items-center justify-between">
                  <div className="pr-4">
                    <span className="block font-semibold">{opt.name}</span>
                    <p className="text-sm text-slate-600">
                      {opt.description || "Frete calculado com base na rota."}
                    </p>
                    <p className="text-sm font-medium text-brand-orange">
                      {opt.days}
                      {opt.estimatedDateMin && opt.estimatedDateMax
                        ? ` · ${formatDeliveryWindow(opt.estimatedDateMin, opt.estimatedDateMax)}`
                        : ""}
                    </p>
                    {(opt.carrier || opt.distanceKm) && (
                      <p className="mt-1 text-xs text-slate-600">
                        {opt.carrier || "Parceiro logístico"}
                        {opt.distanceKm
                          ? ` · rota estimada de ${Math.round(opt.distanceKm)} km`
                          : ""}
                      </p>
                    )}
                    {opt.estimateBasis && (
                      <p className="mt-1 text-xs text-slate-600">
                        Prazo calculado por {opt.estimateBasis}.
                      </p>
                    )}
                  </div>
                  <div className="text-lg font-bold">
                    R$ {opt.price.toFixed(2)}
                  </div>
                </div>
              </button>
            ))}
          </div>
        ) : (
          <div
            className="space-y-3"
            role="radiogroup"
            tabIndex={0}
            aria-label="Escolha o método de entrega"
            onKeyDown={handleShippingKeyDown}
          >
            {fallbackOptions.map((option) => (
              <button
                key={option.id}
                type="button"
                role="radio"
                aria-label={option.name}
                data-shipping-option-id={option.id}
                aria-checked={selectedShipping === option.id}
                onClick={() => {
                  onSelectShipping(option.id);
                }}
                className={`w-full p-4 rounded-lg border-2 text-left cursor-pointer transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-orange focus-visible:ring-offset-2 ${
                  selectedShipping === option.id
                    ? "border-brand-orange bg-brand-orange/5 shadow-md"
                    : "border-slate-200 hover:border-brand-orange/40 hover:bg-slate-50"
                }`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="rounded-lg bg-brand-orange/10 p-2">
                      {option.icon}
                    </div>
                    <div>
                      <span className="block font-semibold">{option.name}</span>
                      <p className="text-sm text-slate-600">
                        {option.description}
                      </p>
                      <p className="text-sm font-medium text-brand-orange">
                        {option.estimatedDays}
                      </p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-lg font-bold">
                      R$ {option.price.toFixed(2)}
                    </p>
                  </div>
                </div>
              </button>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

export const defaultShippingOptions: FallbackOption[] = [
  {
    id: "normal",
    name: "Normal",
    price: 20.0,
    description: "Entrega padrão para todo o Brasil",
    estimatedDays: "3-7 dias",
    icon: <Truck className="h-5 w-5 text-brand-orange" />,
  },
  {
    id: "fast",
    name: "Rápido",
    price: 40.0,
    description: "Entrega expressa para capitais e regiões metropolitanas",
    estimatedDays: "1-3 dias",
    icon: <Clock className="h-5 w-5 text-brand-orange" />,
  },
];

function formatDeliveryWindow(start: string, end: string) {
  const formatter = new Intl.DateTimeFormat("pt-BR", {
    day: "2-digit",
    month: "short",
  });
  return `chega entre ${formatter.format(new Date(start))} e ${formatter.format(
    new Date(end),
  )}`;
}

import { Button } from "@/components/ui/button";
import { ProductCard } from "@/components/shop/ProductCard";
import { ShopEmptyState } from "@/components/shop/ShopEmptyState";
import { ShopPagination } from "@/components/shop/ShopPagination";
import { ShopToolbar } from "@/components/shop/ShopToolbar";
import type { Product } from "@/types/Product";

interface ShopResultsProps {
  compareProducts: Product[];
  currentPage: number;
  filteredProducts: Product[];
  filtersOpen: boolean;
  loading: boolean;
  error?: string | null;
  onRetry?: () => void;
  paginatedProducts: Product[];
  searchTerm: string;
  sortBy: string;
  totalPages: number;
  viewMode: "grid" | "list";
  onAddToCompare: (product: Product) => void;
  onClearFilters: () => void;
  onPageChange: (page: number) => void;
  onSortChange: (value: string) => void;
  onToggleFilters: () => void;
  onViewModeChange: (value: "grid" | "list") => void;
}

export function ShopResults({
  compareProducts,
  currentPage,
  filteredProducts,
  filtersOpen,
  loading,
  error,
  onRetry,
  paginatedProducts,
  searchTerm,
  sortBy,
  totalPages,
  viewMode,
  onAddToCompare,
  onClearFilters,
  onPageChange,
  onSortChange,
  onToggleFilters,
  onViewModeChange,
}: ShopResultsProps) {
  return (
    <div className="flex-1">
      <p
        className="sr-only"
        role="status"
        aria-live="polite"
        aria-atomic="true"
      >
        {loading
          ? "Atualizando resultados."
          : error
            ? "Falha ao carregar os produtos."
            : `${filteredProducts.length} ${
                filteredProducts.length === 1
                  ? "produto encontrado"
                  : "produtos encontrados"
              }${searchTerm ? ` para ${searchTerm}` : ""}.`}
      </p>
      <ShopToolbar
        currentPage={currentPage}
        filtersOpen={filtersOpen}
        resultCount={filteredProducts.length}
        searchTerm={searchTerm}
        sortBy={sortBy}
        totalPages={totalPages}
        viewMode={viewMode}
        onSortChange={onSortChange}
        onToggleFilters={onToggleFilters}
        onViewModeChange={onViewModeChange}
      />

      {loading ? (
        <div
          aria-live="polite"
          aria-busy="true"
          className="rounded-lg border border-gray-200 bg-white p-elevated text-center text-gray-600"
        >
          Carregando produtos...
        </div>
      ) : error ? (
        <div
          role="alert"
          className="rounded-lg border border-red-200 bg-white p-elevated text-center"
        >
          <h2 className="mb-2 text-xl font-bold text-brand-dark">
            Não foi possível carregar a loja
          </h2>
          <p className="mb-5 text-gray-600">{error}</p>
          <Button
            onClick={onRetry}
            className="bg-brand-blue text-white hover:bg-brand-blue/90"
          >
            Tentar novamente
          </Button>
        </div>
      ) : filteredProducts.length === 0 ? (
        <ShopEmptyState onClearFilters={onClearFilters} />
      ) : (
        <>
          <div
            className={
              viewMode === "grid"
                ? "grid auto-rows-fr grid-cols-1 gap-6 sm:grid-cols-2 xl:grid-cols-3"
                : "space-y-4"
            }
          >
            {paginatedProducts.map((product) => (
              <ProductCard
                key={product.id}
                product={product}
                viewMode={viewMode}
                isInCompare={compareProducts.some(
                  (item) => item.id === product.id,
                )}
                onCompare={onAddToCompare}
              />
            ))}
          </div>

          <ShopPagination
            currentPage={currentPage}
            totalPages={totalPages}
            onPageChange={onPageChange}
          />
        </>
      )}
    </div>
  );
}

