import { createContext, ReactNode, useContext, useEffect, useMemo, useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import type { Product } from "@/types/Product";
import { toast } from "@/hooks/use-toast";

type FavoriteRecord = {
  id: number;
  product_id: number;
  product: Product;
};

type FavoritesContextType = {
  favorites: FavoriteRecord[];
  loading: boolean;
  isFavorite: (productId: number) => boolean;
  toggleFavorite: (product: Product) => Promise<boolean>;
  refreshFavorites: () => Promise<void>;
};

const FavoritesContext = createContext<FavoritesContextType | undefined>(undefined);

export const FavoritesProvider = ({ children }: { children: ReactNode }) => {
  const { token, user } = useAuth();
  const [favorites, setFavorites] = useState<FavoriteRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [statusMessage, setStatusMessage] = useState("");

  const announce = (message: string) => {
    setStatusMessage("");
    window.setTimeout(() => setStatusMessage(message), 50);
  };

  const refreshFavorites = async () => {
    if (!token) {
      setFavorites([]);
      return;
    }
    setLoading(true);
    try {
      const response = await fetch("/api/favorites", {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!response.ok) throw new Error("Erro ao buscar favoritos");
      setFavorites(await response.json());
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    refreshFavorites().catch(() => setFavorites([]));
  }, [token, user?.id]);

  const favoriteIds = useMemo(
    () => new Set(favorites.map((favorite) => favorite.product_id)),
    [favorites],
  );

  const toggleFavorite = async (product: Product) => {
    if (!token) throw new Error("AUTH_REQUIRED");
    const removing = favoriteIds.has(product.id);
    let response: Response;
    try {
      response = await fetch(
        `/api/favorites/${product.id}`,
        {
          method: removing ? "DELETE" : "POST",
          headers: { Authorization: `Bearer ${token}` },
        },
      );
    } catch (error) {
      toast({
        title: "Erro ao atualizar favoritos",
        description:
          error instanceof Error
            ? error.message
            : "Não foi possível falar com o servidor.",
        variant: "destructive",
      });
      throw error;
    }

    if (!response.ok) {
      const error = new Error("Não foi possível atualizar os favoritos");
      toast({
        title: "Erro ao atualizar favoritos",
        description: error.message,
        variant: "destructive",
      });
      throw error;
    }

    if (removing) {
      setFavorites((current) =>
        current.filter((favorite) => favorite.product_id !== product.id),
      );
    } else {
      const created = await response.json();
      setFavorites((current) => [created, ...current]);
    }
    announce(
      removing
        ? `${product.name} removido dos favoritos.`
        : `${product.name} adicionado aos favoritos.`,
    );
    toast({
      title: removing ? "Removido dos favoritos" : "Adicionado aos favoritos",
      description: removing
        ? `${product.name} saiu da sua lista.`
        : `${product.name} foi salvo na sua lista.`,
    });
    return !removing;
  };

  return (
    <FavoritesContext.Provider
      value={{
        favorites,
        loading,
        isFavorite: (productId) => favoriteIds.has(productId),
        toggleFavorite,
        refreshFavorites,
      }}
    >
      <p className="sr-only" role="status" aria-live="polite" aria-atomic="true">
        {statusMessage}
      </p>
      {children}
    </FavoritesContext.Provider>
  );
};

export const useFavorites = () => {
  const context = useContext(FavoritesContext);
  if (!context) throw new Error("useFavorites deve ser usado dentro de FavoritesProvider");
  return context;
};

