import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Button } from "../components/ui/button";
import { Input } from "../components/ui/input";
import { Label } from "../components/ui/label";
import {
  Card,
  CardContent,
  CardHeader,
  CardDescription,
} from "../components/ui/card";
import { useTwoFactorVerify } from "../hooks/useTwoFactorVerify";
import { Navbar } from "../components/layout/Navbar";
import Footer from "../components/layout/Footer";
import { Loader2, ShieldCheck } from "lucide-react";
import SkipLink from "../components/ui/SkipLink";

const TwoFactorVerify = ({
  onSuccess,
  method = "google",
}: {
  onSuccess?: () => void;
  method?: "google" | "email";
}) => {
  const [code, setCode] = useState("");
  const navigate = useNavigate();
  const { verify, loading, error, resetError } = useTwoFactorVerify(method);
  const [emailStatus, setEmailStatus] = useState<string | null>(null);
  const [sendingEmail, setSendingEmail] = useState(false);

  const sendEmailCode = async () => {
    setSendingEmail(true);
    try {
      const response = await fetch("/api/2fa/send/email", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("access_token")}`,
        },
      });
      setEmailStatus(
        response.ok
          ? "Código enviado. Confira seu e-mail."
          : "Não foi possível enviar o código.",
      );
    } catch {
      setEmailStatus("Não foi possível enviar o código.");
    } finally {
      setSendingEmail(false);
    }
  };

  const handleVerify = async (e: React.FormEvent) => {
    e.preventDefault();
    resetError();
    const ok = await verify(code);
    if (!ok) return;
    if (onSuccess) onSuccess();
    else navigate("/shop");
  };

  return (
    <div className="flex min-h-screen flex-col bg-slate-50">
      <SkipLink />
      <Navbar />
      <main
        id="main-content"
        tabIndex={-1}
        className="flex flex-1 items-center justify-center px-4 py-12"
      >
        <Card className="w-full max-w-md overflow-hidden border-slate-200 bg-white shadow-sm">
          <div className="h-1.5 bg-gradient-to-r from-brand-blue to-brand-orange" />
          <CardHeader className="flex flex-col items-center gap-2 border-b border-slate-100 bg-slate-50/60 text-center">
            <span className="mb-2 grid h-14 w-14 place-items-center rounded-lg bg-brand-blue/10 text-brand-blue">
              <ShieldCheck className="h-7 w-7" />
            </span>
            <h1 className="text-2xl font-bold text-brand-dark">
              Verificação em duas etapas
            </h1>
            <CardDescription className="leading-6 text-slate-500">
              {method === "email"
                ? "Solicite o código por e-mail para acessar sua conta."
                : "Insira o código gerado pelo seu aplicativo autenticador."}
            </CardDescription>
          </CardHeader>
          <CardContent>
            {method === "email" && (
              <div className="my-4 space-y-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={sendEmailCode}
                  disabled={sendingEmail}
                >
                  {sendingEmail
                    ? "Enviando código..."
                    : "Enviar código por e-mail"}
                </Button>
                {emailStatus && <p role="status">{emailStatus}</p>}
              </div>
            )}
            <form
              onSubmit={handleVerify}
              aria-busy={loading}
              className="space-y-6"
            >
              <div className="space-y-2">
                <Label
                  htmlFor="code"
                  className="text-sm font-medium text-brand-dark"
                >
                  Código de verificação
                </Label>
                <Input
                  id="code"
                  type="text"
                  value={code}
                  onChange={(e) => setCode(e.target.value)}
                  placeholder="Digite o código do app ou e-mail"
                  required
                  autoComplete="one-time-code"
                  className="text-center font-mono text-lg tracking-[0.3em]"
                  maxLength={6}
                  inputMode="numeric"
                  pattern="[0-9]*"
                  aria-invalid={error ? true : undefined}
                  aria-describedby={
                    error
                      ? "two-factor-help two-factor-error"
                      : "two-factor-help"
                  }
                />
                <p id="two-factor-help" className="text-sm text-slate-500">
                  Você pode colar o código recebido ou gerado pelo aplicativo.
                </p>
              </div>
              {error && (
                <div
                  id="two-factor-error"
                  role="alert"
                  className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-center text-sm font-medium text-red-700"
                >
                  {error}
                </div>
              )}
              <Button
                type="submit"
                className="h-11 w-full bg-brand-orange text-white hover:bg-orange-800"
                disabled={loading}
              >
                {loading ? (
                  <span className="flex items-center justify-center">
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Verificando...
                  </span>
                ) : (
                  "Verificar"
                )}
              </Button>
            </form>
          </CardContent>
        </Card>
      </main>
      <Footer variant="minimal" />
    </div>
  );
};

export default TwoFactorVerify;

import { getApiErrorMessage } from "@/lib/apiErrors";
import { useCallback, useEffect, useState } from "react";
import { Link, useParams } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { Navbar } from "@/components/layout/Navbar";
import Footer from "@/components/layout/Footer";
import SkipLink from "@/components/ui/SkipLink";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader } from "@/components/ui/card";

type Action = "approve" | "reject" | "expire" | "refund";
type Payment = {
  order_id: number;
  payment_id: string;
  amount: number;
  method: string;
  status: string;
  status_detail: string;
  order_status: string;
  actions: Action[];
  shared_purchases: { id: number; side: string; status: string }[];
};
const actions: Record<Action, string> = {
  approve: "Aprovar pagamento",
  reject: "Rejeitar pagamento",
  expire: "Expirar cobrança",
  refund: "Estornar pagamento",
};
const states: Record<string, string> = {
  pending: "Aguardando pagamento",
  approved: "Pagamento aprovado",
  rejected: "Pagamento rejeitado",
  cancelled: "Cobrança cancelada",
  refunded: "Pagamento estornado",
  paid: "Pago",
  matched: "Aguardando confirmação dos dois pagamentos",
  completed: "Os dois pagamentos foram confirmados",
  refund_pending: "Cancelamento ou reembolso em processamento",
  expired: "Prazo encerrado",
};

export default function DevelopmentPayment() {
  const { orderId } = useParams();
  const { token } = useAuth();
  const [payment, setPayment] = useState<Payment | null>(null);
  const [loading, setLoading] = useState(true);
  const [pendingAction, setPendingAction] = useState<Action | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const endpoint = `/api/orders/me/${orderId}/development-payment`;

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(endpoint, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const body = await response.json();
      if (!response.ok)
        throw new Error(
          getApiErrorMessage(body, "Pagamento simulado indisponível."),
        );
      setPayment(body);
    } catch (failure) {
      setError(
        failure instanceof Error
          ? failure.message
          : "Não foi possível consultar o pagamento.",
      );
    } finally {
      setLoading(false);
    }
  }, [endpoint, token]);
  useEffect(() => {
    void load();
  }, [load]);

  const act = async (action: Action) => {
    if (pendingAction) return;
    setPendingAction(action);
    setError(null);
    setMessage(null);
    try {
      const response = await fetch(`${endpoint}/${action}`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
      });
      const body = await response.json();
      if (!response.ok)
        throw new Error(
          getApiErrorMessage(body, "Não foi possível atualizar o pagamento."),
        );
      setPayment(body);
      setMessage("Simulação atualizada. O resultado foi salvo no pedido.");
    } catch (failure) {
      setError(
        failure instanceof Error
          ? failure.message
          : "Falha ao atualizar o pagamento.",
      );
    } finally {
      setPendingAction(null);
    }
  };

  return (
    <div className="flex min-h-screen flex-col bg-slate-50">
      <SkipLink />
      <Navbar />
      <main
        id="main-content"
        tabIndex={-1}
        className="container mx-auto flex-1 px-4 py-10"
      >
        <Card className="mx-auto max-w-2xl">
          <CardHeader>
            <p className="text-sm font-semibold text-brand-blue">
              Ambiente de desenvolvimento
            </p>

            <h1 className="text-2xl">Pagamento simulado</h1>

            <p className="text-sm text-slate-600">
              Esta cobrança é fictícia. Nenhum valor será cobrado ou
              transferido.
            </p>
          </CardHeader>
          <CardContent
            className="space-y-6"
            aria-busy={loading || pendingAction !== null}
          >
            {loading && <p role="status">Carregando cobrança...</p>}
            {error && (
              <p role="alert" className="rounded-lg bg-red-50 p-3 text-red-800">
                {error}
              </p>
            )}
            {message && (
              <p
                role="status"
                className="rounded-lg bg-emerald-50 p-3 text-emerald-800"
              >
                {message}
              </p>
            )}
            {payment && (
              <>
                <dl className="grid gap-4 sm:grid-cols-2">
                  <div>
                    <dt className="text-sm text-slate-600">Pedido</dt>
                    <dd className="font-semibold">#{payment.order_id}</dd>
                  </div>
                  <div>
                    <dt className="text-sm text-slate-600">Valor fictício</dt>
                    <dd className="text-xl font-bold">
                      {payment.amount.toLocaleString("pt-BR", {
                        style: "currency",
                        currency: "BRL",
                      })}
                    </dd>
                  </div>
                  <div>
                    <dt className="text-sm text-slate-600">Cobrança</dt>
                    <dd>
                      {payment.status_detail === "development_expired"
                        ? "Cobrança expirada"
                        : states[payment.status] || payment.status}
                    </dd>
                  </div>
                  <div>
                    <dt className="text-sm text-slate-600">Estado do pedido</dt>
                    <dd>
                      {states[payment.order_status] || payment.order_status}
                    </dd>
                  </div>
                </dl>
                {payment.shared_purchases.map((pair) => (
                  <p
                    key={pair.id}
                    className="rounded-lg bg-blue-50 p-4 text-blue-900"
                  >
                    Par compartilhado #{pair.id}:{" "}
                    {states[pair.status] || pair.status}. Cada participante
                    controla o pagamento do seu próprio lado.
                  </p>
                ))}
                <div className="flex flex-wrap gap-3">
                  {payment.actions.map((action) => (
                    <Button
                      key={action}
                      type="button"
                      variant={action === "approve" ? "default" : "outline"}
                      disabled={pendingAction !== null || loading}
                      onClick={() => void act(action)}
                    >
                      {pendingAction === action
                        ? "Atualizando..."
                        : actions[action]}
                    </Button>
                  ))}
                </div>
                <Button asChild variant="outline">
                  <Link to={`/customer/orders/${payment.order_id}`}>
                    Ver pedido
                  </Link>
                </Button>
              </>
            )}
            <Button
              type="button"
              variant="ghost"
              onClick={() => void load()}
              disabled={loading || pendingAction !== null}
            >
              Atualizar cobrança
            </Button>
          </CardContent>
        </Card>
      </main>
      <Footer variant="minimal" />
    </div>
  );
}

import { ArrowLeft } from "lucide-react";
import Footer from "@/components/layout/Footer";
import { Navbar } from "@/components/layout/Navbar";
import SkipLink from "@/components/ui/SkipLink";
import { Button } from "@/components/ui/button";
import { FormErrorSummary } from "@/components/ui/FormErrorSummary";
import { BasicInfoSection } from "@/components/product-edit/BasicInfoSection";
import { EditProductEmptyState } from "@/components/product-edit/EditProductEmptyState";
import { EditProductHeader } from "@/components/product-edit/EditProductHeader";
import { EditProductSectionNav } from "@/components/product-edit/EditProductSectionNav";
import { PricingStockSection } from "@/components/product-edit/PricingStockSection";
import { ProductMediaSection } from "@/components/product-edit/ProductMediaSection";
import { ProductPreviewCard } from "@/components/product-edit/ProductPreviewCard";
import { StyleSection } from "@/components/product-edit/StyleSection";
import { TechnicalDetailsSection } from "@/components/product-edit/TechnicalDetailsSection";
import { editProductSections } from "@/components/product-edit/productEditConfig";
import { useEditProductEditor } from "@/hooks/useEditProductEditor";

const EditProduct = () => {
  const {
    activeSection,
    draggedImages,
    editableProduct,
    fileInputRef,
    focusFieldError,
    handleImageDrop,
    handleSave,
    loadError,
    loading,
    navigate,
    removeImage,
    saving,
    setActiveSection,
    setLocalImage,
    summaryErrors,
    updateProduct,
  } = useEditProductEditor();

  if (loading) {
    return (
      <div className="grid min-h-screen place-items-center bg-slate-50">
        <p role="status">Carregando produto...</p>
      </div>
    );
  }

  if (!editableProduct || loadError) {
    return (
      <EditProductEmptyState message={loadError || "Produto não encontrado"} />
    );
  }

  return (
    <div className="min-h-screen bg-slate-50">
      <SkipLink />
      <Navbar />

      <main
        id="main-content"
        tabIndex={-1}
        className="container mx-auto px-4 py-8 sm:px-6"
      >
        <Button
          type="button"
          variant="ghost"
          onClick={() => navigate("/seller/dashboard")}
          className="-ml-3 mb-4 text-slate-600 hover:bg-brand-blue/5 hover:text-brand-blue"
        >
          <ArrowLeft className="mr-2 h-4 w-4" />
          Voltar ao painel
        </Button>

        <EditProductHeader
          productName={editableProduct.name}
          saving={saving}
          onSave={handleSave}
        />

        <FormErrorSummary
          errors={summaryErrors}
          onSelectError={(error) => focusFieldError(error.fieldId)}
        />

        <div className="grid grid-cols-1 gap-6 xl:grid-cols-4">
          <div className="xl:col-span-1">
            <EditProductSectionNav
              activeSection={activeSection}
              sections={editProductSections}
              onSelectSection={setActiveSection}
            />
          </div>

          <div className="xl:col-span-2">
            <div className="space-y-6">
              {activeSection === "basic" && (
                <BasicInfoSection
                  product={editableProduct}
                  updateProduct={updateProduct}
                />
              )}
              {activeSection === "media" && (
                <ProductMediaSection
                  product={editableProduct}
                  images={draggedImages}
                  fileInputRef={fileInputRef}
                  onImageDrop={handleImageDrop}
                  onImageSelect={setLocalImage}
                  onRemoveImage={removeImage}
                />
              )}
              {activeSection === "pricing" && (
                <PricingStockSection
                  product={editableProduct}
                  updateProduct={updateProduct}
                />
              )}
              {activeSection === "details" && (
                <TechnicalDetailsSection
                  product={editableProduct}
                  updateProduct={updateProduct}
                />
              )}
              {activeSection === "style" && (
                <StyleSection
                  product={editableProduct}
                  updateProduct={updateProduct}
                />
              )}
            </div>
          </div>

          <div className="xl:col-span-1">
            <ProductPreviewCard
              product={editableProduct}
              imageUrl={draggedImages[0]}
            />
          </div>
        </div>
      </main>

      <Footer variant="minimal" />
    </div>
  );
};

export default EditProduct;

import { type KeyboardEvent, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { ChevronLeft, ArrowRight } from "lucide-react";
import { useFocusReturnOnClose } from "@/hooks/useFocusReturnOnClose";

interface FootSelectionModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSelect: (foot: "left" | "right") => void;
  onBack: () => void;
}

export const FootSelectionModal = ({
  open,
  onOpenChange,
  onSelect,
  onBack,
}: FootSelectionModalProps) => {
  useFocusReturnOnClose(open);
  const [selectedFoot, setSelectedFoot] = useState<"left" | "right" | null>(
    null
  );
  const leftButtonRef = useRef<HTMLButtonElement>(null);
  const rightButtonRef = useRef<HTMLButtonElement>(null);

  const navigate = useNavigate();

  const selectFoot = (foot: "left" | "right") => {
    setSelectedFoot(foot);
    requestAnimationFrame(() => {
      if (foot === "left") leftButtonRef.current?.focus();
      else rightButtonRef.current?.focus();
    });
  };

  const handleRadioKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const keys = ["ArrowDown", "ArrowRight", "ArrowUp", "ArrowLeft", "Home", "End"];
    if (!keys.includes(event.key)) return;

    event.preventDefault();
    if (event.key === "Home") {
      selectFoot("left");
      return;
    }
    if (event.key === "End") {
      selectFoot("right");
      return;
    }

    selectFoot(selectedFoot === "left" ? "right" : "left");
  };

  const handleConfirm = () => {
    if (selectedFoot) {
      onSelect(selectedFoot);
      onOpenChange(false);
      setSelectedFoot(null);
    }
  };

  const handleCancel = () => {
    navigate("/seller/dashboard");
  };

  const handleBack = () => {
    onBack();
    setSelectedFoot(null);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Seleção do pé</DialogTitle>
          <DialogDescription>
            Escolha se você deseja cadastrar um pé direito ou esquerdo
          </DialogDescription>
        </DialogHeader>

        <div
          className="mt-4 grid grid-cols-1 gap-4"
          role="radiogroup"
          aria-label="Pé do produto"
          tabIndex={-1}
          onKeyDown={handleRadioKeyDown}
        >
          <button
            ref={leftButtonRef}
            type="button"
            role="radio"
            aria-label="Pé esquerdo"
            aria-checked={selectedFoot === "left"}
            tabIndex={selectedFoot === null || selectedFoot === "left" ? 0 : -1}
            className="rounded-lg text-left focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-brand-blue focus-visible:ring-offset-2"
            onClick={() => setSelectedFoot("left")}
          >
          <Card
            className={`cursor-pointer transition-all ${
              selectedFoot === "left"
                ? "ring-2 ring-blue-500 bg-blue-50"
                : "hover:bg-gray-50"
            }`}
          >
            <CardContent className="p-card text-center">
              <div className="h-12 w-12 mx-auto mb-3 bg-blue-100 rounded-full flex items-center justify-center">
                <span className="text-2xl">🦶</span>
              </div>
              <h3 className="font-semibold text-lg mb-2">Pé esquerdo</h3>
              <p className="text-gray-600 text-sm">
                Calçado para o pé esquerdo
              </p>
            </CardContent>
          </Card>
          </button>

          <button
            ref={rightButtonRef}
            type="button"
            role="radio"
            aria-label="Pé direito"
            aria-checked={selectedFoot === "right"}
            tabIndex={selectedFoot === "right" ? 0 : -1}
            className="rounded-lg text-left focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-brand-blue focus-visible:ring-offset-2"
            onClick={() => setSelectedFoot("right")}
          >
          <Card
            className={`cursor-pointer transition-all ${
              selectedFoot === "right"
                ? "ring-2 ring-blue-500 bg-blue-50"
                : "hover:bg-gray-50"
            }`}
          >
            <CardContent className="p-card text-center">
              <div className="h-12 w-12 mx-auto mb-3 bg-green-100 rounded-full flex items-center justify-center">
                <span className="text-2xl transform scale-x-[-1]">🦶</span>
              </div>
              <h3 className="font-semibold text-lg mb-2">Pé direito</h3>
              <p className="text-gray-600 text-sm">Calçado para o pé direito</p>
            </CardContent>
          </Card>
          </button>
        </div>

        <div className="flex gap-3 mt-6">
          <Button variant="outline" className="gap-2" onClick={handleBack}>
            <ChevronLeft className="h-4 w-4" />
            Voltar
          </Button>
          <Button variant="outline" className="flex-1" onClick={handleCancel}>
            Cancelar
          </Button>
          <Button
            className="flex-1 gap-2"
            onClick={handleConfirm}
            disabled={!selectedFoot}
          >
            Continuar
            <ArrowRight className="h-4 w-4" />
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default FootSelectionModal;

import { type KeyboardEvent, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
